// ── NEXO LOGO SVG COMPONENT ──────────────────────────────────────────────────
function NexoLogoIcon({size=40}){
  return(
    <svg width={size} height={size} viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" style={{display:"block",flexShrink:0}}>
      <defs>
        <linearGradient id="nlGrad" x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#6366F1"/>
          <stop offset="60%" stopColor="#0066FF"/>
          <stop offset="100%" stopColor="#00C8A0"/>
        </linearGradient>
        <linearGradient id="nlGlow" x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#818CF8" stopOpacity="0.3"/>
          <stop offset="100%" stopColor="#0066FF" stopOpacity="0"/>
        </linearGradient>
      </defs>
      {/* Background */}
      <rect width="40" height="40" rx="11" fill="url(#nlGrad)"/>
      {/* Glow overlay */}
      <rect width="40" height="40" rx="11" fill="url(#nlGlow)"/>
      {/* Grid lines — faint */}
      <path d="M8 30 L32 30" stroke="rgba(255,255,255,0.12)" strokeWidth="0.8"/>
      <path d="M8 22 L32 22" stroke="rgba(255,255,255,0.08)" strokeWidth="0.8"/>
      {/* Chart line */}
      <path d="M8 28 L14 20 L20 24 L28 11" stroke="white" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"/>
      {/* Area fill under chart */}
      <path d="M8 28 L14 20 L20 24 L28 11 L28 30 L8 30 Z" fill="rgba(255,255,255,0.07)"/>
      {/* Peak dot */}
      <circle cx="28" cy="11" r="3" fill="#00E58F"/>
      <circle cx="28" cy="11" r="1.4" fill="white"/>
    </svg>
  );
}

// ── CASHTAG + @MENTION RENDERER ───────────────────────────────────────────────
function renderWithCashtags(text, onTickerClick, onMentionClick){
  if(!text) return text;
  // Detecta $TICKER (cashtag verde) y @TICKER (mención oscura)
  const parts = text.split(/(\$[A-Z]{1,5}|@[A-Z0-9]{1,15})/g);
  return parts.map((part, i) => {
    if(/^\$[A-Z]{1,5}$/.test(part)){
      // Cashtag — verde brillante
      return <span key={i} onClick={()=>onTickerClick&&onTickerClick(part.slice(1))}
        style={{color:"#007A48",fontWeight:700,cursor:"pointer",background:"rgba(0,160,96,0.1)",borderRadius:4,padding:"1px 5px",border:"1px solid rgba(0,160,96,0.25)",fontSize:"0.9em",letterSpacing:0.3,fontFamily:"monospace"}}
        onMouseEnter={e=>{e.currentTarget.style.background="rgba(0,229,143,0.18)";e.currentTarget.style.boxShadow="0 0 8px rgba(0,229,143,0.3)";}}
        onMouseLeave={e=>{e.currentTarget.style.background="rgba(0,229,143,0.1)";e.currentTarget.style.boxShadow="none";}}
      >{part}</span>;
    }
    if(/^@[A-Z0-9]{1,15}$/.test(part)){
      // @Mención — chip azul, abre vista del ticker
      const sym = part.slice(1);
      return <span key={i} onClick={()=>onMentionClick&&onMentionClick(sym)}
        style={{color:"#0066FF",fontWeight:700,cursor:"pointer",background:"rgba(0,102,255,0.1)",borderRadius:6,padding:"2px 8px",border:"1px solid rgba(0,102,255,0.3)",fontSize:"0.88em",letterSpacing:0.2,fontFamily:"monospace",display:"inline-block",transition:"all 0.15s"}}
        onMouseEnter={e=>{e.currentTarget.style.background="rgba(0,102,255,0.2)";e.currentTarget.style.borderColor="rgba(0,102,255,0.55)";e.currentTarget.style.color="#60A5FA";e.currentTarget.style.boxShadow="0 0 8px rgba(0,102,255,0.2)";}}
        onMouseLeave={e=>{e.currentTarget.style.background="rgba(0,102,255,0.1)";e.currentTarget.style.borderColor="rgba(0,102,255,0.3)";e.currentTarget.style.color="#0066FF";e.currentTarget.style.boxShadow="none";}}
      >{part}</span>;
    }
    return part;
  });
}

