function IpoCalendarPage() {
  const [yearTab, setYearTab] = useState("2026");
  const [filter,  setFilter]  = useState("all");
  const [ipos,    setIpos]    = useState(IPOS_2026);
  const [loading, setLoading] = useState(true);
  const [source,  setSource]  = useState("local");
  const [lastUp,  setLastUp]  = useState("");
  const today = new Date().toISOString().split("T")[0];

  const STATUS = {
    upcoming:{color:C.accent,              bg:C.accentDim,              label:"Upcoming"},
    priced:  {color:C.purple,              bg:C.purpleBg,               label:"Priced"},
    trading: {color:C.bull,                bg:C.bullBg,                  label:"Trading"},
    expected:{color:"#F59E0B",             bg:"rgba(245,158,11,0.1)",   label:"Esperado"},
    rumored: {color:"#94A3B8",             bg:"rgba(148,163,184,0.1)", label:"Rumor"},
  };

  const autoStatus = (ipo) => {
    if(!ipo.date||ipo.date.includes("Q")||ipo.date.includes("+")) return "upcoming";
    const d = new Date(ipo.date);
    const diffDays = (d - new Date()) / (1000*60*60*24);
    if(diffDays > 7)  return "upcoming";
    if(diffDays > -3) return "priced";
    return "trading";
  };

  const fetch2026 = () => {
    setLoading(true);
    const withAutoStatus = IPOS_2026.map(ipo => ({...ipo, status: autoStatus(ipo)}));
    setIpos(withAutoStatus);
    fetch("/api/ipos")
      .then(r=>r.json())
      .then(d=>{
        if(d.ipos && d.ipos.length > 0){
          const merged = [...d.ipos];
          IPOS_2026.forEach(seed=>{
            const exists = merged.find(x=>x.ticker===seed.ticker||x.company.toLowerCase().includes(seed.company.split(" ")[0].toLowerCase()));
            if(!exists) merged.push({...seed, status: autoStatus(seed)});
            else{ exists.desc=exists.desc||seed.desc; exists.sector=exists.sector||seed.sector; exists.status=autoStatus(exists); }
          });
          merged.sort((a,b)=>{
            const order={upcoming:0,priced:1,trading:2};
            if(order[a.status]!==order[b.status]) return order[a.status]-order[b.status];
            return (a.date||"9999").localeCompare(b.date||"9999");
          });
          setIpos(merged);
          setSource(d.source==="fmp"?"live":"local");
        }
      })
      .catch(()=>{})
      .finally(()=>{
        setLoading(false);
        setLastUp(new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}));
      });
  };
  const fetchData = fetch2026; // alias para compatibilidad

  useEffect(()=>{
    setFilter("all");
    if(yearTab==="2026"){
      fetch2026();
      const timer = setInterval(fetch2026, 5*60*1000); // auto-refresh cada 5 min
      return ()=>clearInterval(timer);
    } else if(yearTab==="2027"){
      setIpos(IPOS_2027); setSource("curated"); setLoading(false);
    } else {
      setIpos(IPOS_2028); setSource("curated"); setLoading(false);
    }
  },[yearTab]);

  const rows = ipos.filter(ipo => filter==="all" || ipo.status===filter);
  const counts = {
    all:ipos.length,
    upcoming:ipos.filter(x=>x.status==="upcoming").length,
    priced:ipos.filter(x=>x.status==="priced").length,
    trading:ipos.filter(x=>x.status==="trading").length,
    expected:ipos.filter(x=>x.status==="expected").length,
    rumored:ipos.filter(x=>x.status==="rumored").length,
  };

  const YEAR_TABS=[
    {k:"2026", label:"2026", sub:"Live", color:C.accent},
    {k:"2027", label:"2027", sub:"Esperados", color:"#F59E0B"},
    {k:"2028+",label:"2028+",sub:"Rumores",   color:"#94A3B8"},
  ];

  const filterBtns = yearTab==="2026"
    ? [{k:"all",l:`Todos (${counts.all})`},{k:"upcoming",l:`🔜 Upcoming (${counts.upcoming})`},{k:"priced",l:`💜 Priced (${counts.priced})`},{k:"trading",l:`✅ Trading (${counts.trading})`}]
    : yearTab==="2027"
      ? [{k:"all",l:`Todos (${counts.all})`},{k:"expected",l:`⭐ Esperado (${counts.expected})`}]
      : [{k:"all",l:`Todos (${counts.all})`},{k:"rumored",l:`💭 Rumor (${counts.rumored})`}];

  return(
    <div style={{maxWidth:920,margin:"0 auto"}}>
      <div style={{background:C.card,borderRadius:16,padding:"20px 24px",marginBottom:16,boxShadow:C.shadow,border:`1px solid ${C.border}`}}>
        <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:14}}>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
              <div style={{fontSize:20,fontWeight:800,color:C.text}}>🚀 IPO Calendar</div>
              {yearTab==="2026" && (source==="live"
                ? <span style={{fontSize:10,fontWeight:700,color:C.bull,background:C.bullBg,borderRadius:10,padding:"2px 8px"}}>● LIVE</span>
                : <span style={{fontSize:10,fontWeight:700,color:C.muted2,background:C.card2,borderRadius:10,padding:"2px 8px",border:`1px solid ${C.border}`}}>CURATED</span>
              )}
              {yearTab!=="2026" && <span style={{fontSize:10,fontWeight:700,color:"#F59E0B",background:"rgba(245,158,11,0.1)",borderRadius:10,padding:"2px 8px"}}>CURATED</span>}
              <span style={{fontSize:11,color:C.muted2}}>{ipos.length} IPOs</span>
              {lastUp && yearTab==="2026" && <span style={{fontSize:10,color:C.muted2}}>· {lastUp}</span>}
              {yearTab==="2026" && <span style={{fontSize:10,fontWeight:700,color:"#10B981",background:"rgba(16,185,129,0.08)",borderRadius:10,padding:"2px 8px"}}>↻ Auto 5min</span>}
            </div>
            <div style={{fontSize:12,color:C.muted,marginTop:2}}>Ofertas públicas — precios, fechas, sectores y estado en tiempo real</div>
          </div>
          {yearTab==="2026" && (
            <button onClick={fetch2026} disabled={loading}
              style={{display:"flex",alignItems:"center",gap:8,padding:"10px 20px",borderRadius:12,border:`2px solid ${C.accent}`,background:loading?C.card2:C.accentDim,color:C.accent,fontSize:13,fontWeight:800,cursor:loading?"not-allowed":"pointer",fontFamily:"inherit",transition:"all 0.15s",flexShrink:0}}
              onMouseEnter={e=>{if(!loading){e.currentTarget.style.background=C.accent;e.currentTarget.style.color="#fff";}}}
              onMouseLeave={e=>{e.currentTarget.style.background=C.accentDim;e.currentTarget.style.color=C.accent;}}>
              <span style={{fontSize:16,display:"inline-block",animation:loading?"spin 1s linear infinite":"none"}}>⟳</span>
              {loading?"Actualizando...":"Refresh"}
            </button>
          )}
        </div>

        {/* Year tabs */}
        <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
          {YEAR_TABS.map(t=>(
            <button key={t.k} onClick={()=>setYearTab(t.k)}
              style={{padding:"6px 18px",borderRadius:20,border:`2px solid ${yearTab===t.k?t.color:C.border}`,background:yearTab===t.k?t.color+"18":"transparent",cursor:"pointer",transition:"all 0.15s",display:"flex",alignItems:"center",gap:5}}>
              <span style={{fontSize:13,fontWeight:800,color:yearTab===t.k?t.color:C.muted}}>{t.label}</span>
              <span style={{fontSize:10,color:yearTab===t.k?t.color:C.muted2,fontWeight:600}}>{t.sub}</span>
            </button>
          ))}
        </div>

        {/* Status filter */}
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          {filterBtns.map(({k,l})=>(
            <button key={k} onClick={()=>setFilter(k)} style={{background:filter===k?C.accent:"transparent",color:filter===k?"#fff":C.muted,border:`1.5px solid ${filter===k?C.accent:C.border}`,borderRadius:20,padding:"5px 13px",fontSize:12,fontWeight:600,cursor:"pointer",transition:"all 0.15s"}}>{l}</button>
          ))}
        </div>
      </div>

      <div style={{display:"grid",gap:10}}>
        {rows.length===0 && <div style={{textAlign:"center",padding:"40px",color:C.muted}}>Sin IPOs con ese filtro.</div>}
        {rows.map((ipo,i)=>{
          const st = STATUS[ipo.status] || STATUS.upcoming;
          const isFuture = !ipo.date || ipo.date >= today;
          return(
            <div key={i} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:"16px 22px",boxShadow:C.shadow,display:"grid",gridTemplateColumns:"1fr auto",gap:16,alignItems:"center",transition:"box-shadow 0.15s"}}
              onMouseEnter={e=>e.currentTarget.style.boxShadow=C.shadowMd}
              onMouseLeave={e=>e.currentTarget.style.boxShadow=C.shadow}>
              <div>
                <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6,flexWrap:"wrap"}}>
                  <div style={{fontWeight:900,fontSize:15,color:C.text}}>{ipo.company}</div>
                  {ipo.ticker && ipo.ticker!=="—" && ipo.ticker!=="TBD" && <div style={{fontWeight:800,fontSize:11,color:C.accent,background:C.accentDim,borderRadius:8,padding:"2px 8px"}}>{ipo.ticker}</div>}
                  {ipo.exchange && ipo.exchange!=="—" && ipo.exchange!=="TBD" && <div style={{fontSize:11,color:C.muted,background:C.card2,borderRadius:8,padding:"2px 8px",border:`1px solid ${C.border}`}}>{ipo.exchange}</div>}
                  <span style={{fontSize:11,fontWeight:700,color:st.color,background:st.bg,borderRadius:10,padding:"2px 9px"}}>{st.label}</span>
                </div>
                {ipo.desc && <div style={{fontSize:12,color:C.muted,marginBottom:6,lineHeight:1.5}}>{ipo.desc}</div>}
                <div style={{display:"flex",gap:14,flexWrap:"wrap"}}>
                  {ipo.sector && ipo.sector!=="Mercado" && <span style={{fontSize:12,color:C.muted}}><b style={{color:C.text}}>Sector:</b> {ipo.sector}</span>}
                  {ipo.raise  && ipo.raise!=="—"  && <span style={{fontSize:12,color:C.muted}}><b style={{color:C.text}}>Recaudación:</b> {ipo.raise}</span>}
                  {ipo.valuation && <span style={{fontSize:12,color:C.muted}}><b style={{color:C.text}}>Valoración:</b> {ipo.valuation}</span>}
                  {ipo.shares && ipo.shares!=="—" && <span style={{fontSize:12,color:C.muted}}>{ipo.shares}</span>}
                </div>
              </div>
              <div style={{textAlign:"right",minWidth:110}}>
                {ipo.range && ipo.range!=="Por definir" && ipo.range!=="TBD" && (
                  <>
                    <div style={{fontSize:20,fontWeight:900,color:C.text,marginBottom:2}}>{ipo.range}</div>
                    <div style={{fontSize:10,color:C.muted2,marginBottom:6}}>precio/acción</div>
                  </>
                )}
                {ipo.date && ipo.date!=="—" && (
                  <div style={{fontSize:12,fontWeight:700,color:isFuture?C.accent:C.muted}}>
                    {(() => { try { return new Date(ipo.date+"T12:00:00").toLocaleDateString("es-ES",{day:"numeric",month:"short",year:"numeric"}); } catch(e){ return ipo.date; } })()}
                  </div>
                )}
                {ipo.url && (
                  <a href={ipo.url} target="_blank" rel="noopener noreferrer"
                    style={{fontSize:11,color:C.accent,textDecoration:"none",display:"block",marginTop:4}}>
                    Ver prospecto →
                  </a>
                )}
              </div>
            </div>
          );
        })}
      </div>
      <div style={{textAlign:"center",padding:"16px 0",fontSize:11,color:C.muted2}}>
        {yearTab==="2026"
          ? (source==="live" ? "⚡ Datos en tiempo real via FMP" : "📋 Lista curada — agrega FMP_API_KEY en Vercel para tiempo real")
          : yearTab==="2027" ? "⭐ Empresas con alta probabilidad de IPO en 2027 según analistas" : "💭 Rumores y expectativas del mercado — sin fecha confirmada"}
        {" · "}Siempre verifica en SEC EDGAR antes de invertir
      </div>
    </div>
  );
}

// ── STOCK SCREENER PAGE (page 17) — VIP ───────────────────────────────────────
const SCREENER_PRESETS = [
  {k:"gainers",    label:"📈 Top Ganadores",   desc:"Las más alcistas hoy"},
  {k:"losers",     label:"📉 Top Perdedores",  desc:"Las más bajistas hoy"},
  {k:"active",     label:"🔥 Más Activas",     desc:"Mayor volumen del mercado"},
  {k:"undervalued",label:"💎 Subvaloradas",    desc:"Crecimiento con buen precio"},
  {k:"growth",     label:"🚀 Crecimiento Tech",desc:"Tecnología con alto potencial"},
  {k:"dividend",   label:"💰 Dividendos",      desc:"Carteras anchor de dividendo"},
];

function ScreenerPage({isPremium, onNeedPremium}) {
  const [screen,  setScreen]  = useState("gainers");
  const [quotes,  setQuotes]  = useState([]);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState(false);

  useEffect(()=>{
    if(!isPremium) return;
    setLoading(true); setError(false);
    fetch(`/api/screener?screen=${screen}`)
      .then(r=>r.json())
      .then(d=>{ setQuotes(d.quotes||[]); setLoading(false); })
      .catch(()=>{ setError(true); setLoading(false); });
  },[screen, isPremium]);

  const fmt$ = v => v>=1e9 ? `$${(v/1e9).toFixed(1)}B` : v>=1e6 ? `$${(v/1e6).toFixed(0)}M` : v ? `$${v.toFixed(2)}` : "—";
  const fmtPct = v => v ? `${v>0?"+":""}${v.toFixed(2)}%` : "—";

  if(!isPremium) return(
    <div style={{position:"relative",overflow:"hidden",minHeight:480,background:"rgba(7,11,20,0.98)"}}>
      {/* Preview borrosa */}
      <div style={{filter:"blur(5px)",pointerEvents:"none",userSelect:"none",padding:"20px 16px"}}>
        <div style={{fontWeight:800,color:"#F59E0B",fontSize:13,marginBottom:14}}>🔬 Stock Screener PREMIUM</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(220px,1fr))",gap:10,marginBottom:14}}>
          {SCREENER_PRESETS.map((p,i)=>(
            <div key={i} style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.07)",borderRadius:12,padding:"14px 16px",cursor:"pointer"}}>
              <div style={{fontSize:14,fontWeight:700,color:"#E2E8F0",marginBottom:4}}>{p.label}</div>
              <div style={{fontSize:11,color:"#475569"}}>{p.desc}</div>
            </div>
          ))}
        </div>
        <div style={{background:"rgba(255,255,255,0.02)",border:"1px solid rgba(255,255,255,0.06)",borderRadius:12,overflow:"hidden"}}>
          {[{t:"NVDA",n:"NVIDIA Corp.",p:"$224.36",c:"+6.26%",vol:"58M",mc:"$5.5T"},{t:"AAPL",n:"Apple Inc.",p:"$306.21",c:"-1.84%",vol:"24M",mc:"$4.6T"},{t:"TSLA",n:"Tesla Inc.",p:"$332.18",c:"-4.12%",vol:"92M",mc:"$1.1T"}].map((r,i)=>(
            <div key={i} style={{display:"flex",gap:12,padding:"10px 16px",borderBottom:"1px solid rgba(255,255,255,0.04)",alignItems:"center"}}>
              <span style={{fontFamily:"monospace",fontWeight:900,color:"#F59E0B",width:50}}>{r.t}</span>
              <span style={{flex:1,color:"#64748B",fontSize:12}}>{r.n}</span>
              <span style={{color:"#E2E8F0",fontWeight:700}}>{r.p}</span>
              <span style={{color:r.c.startsWith("+")?"#00D26A":"#FF4D6A",fontWeight:700,width:60,textAlign:"right"}}>{r.c}</span>
            </div>
          ))}
        </div>
      </div>
      {/* Degradado + CTA */}
      <div style={{position:"absolute",bottom:0,left:0,right:0,height:"70%",background:"linear-gradient(transparent,rgba(7,11,20,0.99))",pointerEvents:"none"}}/>
      <div style={{position:"absolute",bottom:0,left:0,right:0,display:"flex",flexDirection:"column",alignItems:"center",padding:"0 20px 48px"}}>
        <div style={{background:"rgba(10,14,26,0.98)",border:"1px solid rgba(245,158,11,0.35)",borderRadius:20,padding:"28px 32px",textAlign:"center",maxWidth:380,boxShadow:"0 8px 40px rgba(0,0,0,0.7)"}}>
          <div style={{fontSize:36,marginBottom:10}}>🔬</div>
          <h2 style={{color:"#F1F5F9",fontWeight:900,fontSize:22,margin:"0 0 8px"}}>Stock Screener PREMIUM</h2>
          <p style={{color:"#64748B",fontSize:13,lineHeight:1.65,margin:"0 0 22px"}}>Filtra 10,000+ acciones por momentum, valoración, dividendo y crecimiento.</p>
          <button onClick={onNeedPremium} style={{background:"linear-gradient(135deg,#D97706,#F59E0B)",border:"none",borderRadius:12,padding:"14px 32px",color:"#fff",fontSize:15,fontWeight:800,cursor:"pointer",boxShadow:"0 0 28px rgba(217,119,6,0.45)",width:"100%",marginBottom:10}}>
            ✦ Activar PREMIUM — $9.99/mes
          </button>
          <div style={{fontSize:11,color:"#475569"}}>✓ Cancela cuando quieras · ✓ Acceso inmediato</div>
        </div>
      </div>
    </div>
  );

  const preset = SCREENER_PRESETS.find(p=>p.k===screen);

  return(
    <div style={{maxWidth:960,margin:"0 auto"}}>
      <div style={{background:C.card,borderRadius:16,padding:"20px 24px",marginBottom:16,boxShadow:C.shadow,border:`1px solid ${C.border}`}}>
        <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:14}}>
          <span style={{fontSize:30}}>🔍</span>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <div style={{fontSize:20,fontWeight:800,color:C.text}}>Stock Screener</div>
              <span style={{fontSize:11,fontWeight:700,background:"linear-gradient(135deg,#F59E0B,#B45309)",color:"#fff",borderRadius:20,padding:"3px 10px"}}>PREMIUM</span>
            </div>
            <div style={{fontSize:12,color:C.muted}}>{preset?.desc} · {quotes.length} resultados</div>
          </div>
        </div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          {SCREENER_PRESETS.map(({k,label})=>(
            <button key={k} onClick={()=>setScreen(k)} style={{background:screen===k?"linear-gradient(135deg,#F59E0B,#B45309)":"transparent",color:screen===k?"#fff":C.muted,border:`1.5px solid ${screen===k?"transparent":C.border}`,borderRadius:20,padding:"6px 14px",fontSize:12,fontWeight:600,cursor:"pointer",transition:"all 0.15s",boxShadow:screen===k?"0 4px 12px rgba(217,119,6,0.3)":"none"}}>{label}</button>
          ))}
        </div>
      </div>

      {loading && <div style={{textAlign:"center",padding:"40px",color:C.muted,fontSize:14}}>Cargando screener... ⏳</div>}
      {error   && <div style={{textAlign:"center",padding:"40px",color:C.bear,fontSize:14}}>Error al cargar datos. Intenta de nuevo.</div>}

      {!loading && !error && quotes.length > 0 && (
        <div style={{background:C.card,borderRadius:16,boxShadow:C.shadow,border:`1px solid ${C.border}`,overflowX:"auto"}}>
          <div style={{minWidth:720}}>
            <div style={{display:"grid",gridTemplateColumns:"80px minmax(140px,1fr) 90px 90px 70px 100px 90px",background:C.card2,borderBottom:`1px solid ${C.border}`,padding:"10px 20px",gap:8,borderRadius:"16px 16px 0 0"}}>
              {["Ticker","Empresa","Precio","Cambio %","P/E","Mkt Cap","Volumen"].map(h=>(
                <div key={h} style={{fontSize:10,fontWeight:700,color:C.muted2,letterSpacing:0.5}}>{h.toUpperCase()}</div>
              ))}
            </div>
            {quotes.slice(0,25).map((q,i)=>{
              const chg    = q.regularMarketChangePercent || 0;
              const isPos  = chg >= 0;
              return(
                <div key={i} style={{display:"grid",gridTemplateColumns:"80px minmax(140px,1fr) 90px 90px 70px 100px 90px",gap:8,padding:"12px 20px",borderBottom:`1px solid ${C.border}`,cursor:"pointer",transition:"background 0.12s"}}
                  onMouseEnter={e=>e.currentTarget.style.background=C.card2}
                  onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                  <div style={{fontWeight:800,fontSize:13,color:C.accent}}>{q.symbol}</div>
                  <div style={{minWidth:0}}>
                    <div style={{fontSize:12,fontWeight:600,color:C.text,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{q.shortName||q.longName||q.symbol}</div>
                    <div style={{fontSize:10,color:C.muted2}}>{q.exchange||""}</div>
                  </div>
                  <div style={{fontSize:13,fontWeight:700,color:C.text}}>${q.regularMarketPrice?.toFixed(2)||"—"}</div>
                  <div style={{fontSize:13,fontWeight:700,color:isPos?C.bull:C.bear}}>{fmtPct(chg)}</div>
                  <div style={{fontSize:12,color:C.muted}}>{q.trailingPE?.toFixed(1)||"—"}</div>
                  <div style={{fontSize:12,color:C.muted}}>{fmt$(q.marketCap)}</div>
                  <div style={{fontSize:12,color:C.muted}}>{q.regularMarketVolume ? (q.regularMarketVolume/1e6).toFixed(1)+"M" : "—"}</div>
                </div>
              );
            })}
          </div>
        </div>
      )}
      {!loading && !error && quotes.length===0 && <div style={{textAlign:"center",padding:"40px",color:C.muted}}>Sin resultados. Intenta otro filtro.</div>}
    </div>
  );
}

