// ── BOT POSTS de NexoTrade Research (después de IDEAS_DATA para poder usarla) ─
const BOT_POSTS = IDEAS_DATA.slice(0,10).map((idea, i) => {
  const persona = BOT_PERSONAS[i % BOT_PERSONAS.length];
  const textFn  = BOT_TEXT_TEMPLATES[persona.style];
  return {
    id:`bot-${idea.id}`,
    user: persona.user,
    avatar: persona.avatar,
    avatarColor: persona.avatarColor,
    badge: persona.badge,
    ticker: idea.ticker,
    sentiment: idea.signal==="COMPRA"?"bull":idea.signal==="VENTA"?"bear":"neutral",
    text: textFn(idea),
    likes:  60 + (idea.id*19) % 140,
    comments: 8 + (idea.id*7) % 35,
    reposts:  4 + (idea.id*3) % 22,
    time: idea.published,
    tags: idea.tags,
    // Cada 2 bots muestran mini chart de precio (los de análisis técnico)
    showChart: i % 2 === 0,
  };
});

// Nombres de empresa para los tickers más comunes
const TICKER_NAMES={
  NVDA:"NVIDIA",AAPL:"Apple",TSLA:"Tesla",MSFT:"Microsoft",META:"Meta",
  AMZN:"Amazon",GOOGL:"Alphabet",PLTR:"Palantir",AMD:"AMD",SPY:"S&P 500 ETF",
  SMCI:"Super Micro",COIN:"Coinbase",QQQ:"Nasdaq ETF",MSFT:"Microsoft",
  BTC:"Bitcoin",ETH:"Ethereum",SOL:"Solana",BNB:"Binance Coin",
  XRP:"Ripple",ADA:"Cardano",DOGE:"Dogecoin",AVAX:"Avalanche",
  JPM:"JPMorgan",BAC:"Bank of America",GS:"Goldman Sachs",
  NFLX:"Netflix",DIS:"Disney",UBER:"Uber",LYFT:"Lyft",
  SHOP:"Shopify",SQ:"Block (Square)",PYPL:"PayPal",V:"Visa",MA:"Mastercard",
};

// Renderiza texto con $TICKER clicables y nombre de empresa
function renderBotText(text, onTickerClick){
  const parts = text.split(/(\$[A-Z]{1,5})/g);
  return parts.map((part,i)=>{
    const match = part.match(/^\$([A-Z]{1,5})$/);
    if(match){
      const tk = match[1];
      const name = TICKER_NAMES[tk];
      return(
        <span key={i} onClick={()=>onTickerClick&&onTickerClick(tk)}
          title={name?`Ver ${name} en NexoTrade`:`Ver $${tk} en NexoTrade`}
          style={{color:C.accent,fontWeight:800,cursor:"pointer",borderBottom:`1.5px solid ${C.accent}`,paddingBottom:1,transition:"opacity 0.15s",display:"inline-flex",alignItems:"center",gap:2}}
          onMouseEnter={e=>e.currentTarget.style.opacity="0.75"}
          onMouseLeave={e=>e.currentTarget.style.opacity="1"}>
          {part}{name&&<span style={{fontSize:"0.75em",fontWeight:600,color:C.muted,borderBottom:"none"}}> ({name})</span>}
        </span>
      );
    }
    return <span key={i}>{part}</span>;
  });
}

function BotPostCard({post,onTickerClick,lang}){
  const isEN = lang==="en";
  const isBull = post.sentiment==="bull";
  const isBear = post.sentiment==="bear";
  const sentColor = isBull?C.bull:isBear?C.bear:C.muted;
  const sentBg    = isBull?C.bullBg:isBear?C.bearBg:C.accentDim;
  const sentLabel = isBull?"▲ BUY":isBear?"▼ SELL":"◆ HOLD";
  const mainName  = TICKER_NAMES[post.ticker];
  return(
    <div style={{background:C.card,border:`1.5px solid ${isBull?"rgba(22,163,74,0.22)":isBear?"rgba(220,38,38,0.22)":C.border}`,borderRadius:16,padding:"14px 16px",marginBottom:6,boxShadow:C.shadow,transition:"transform 0.18s"}}
      onMouseEnter={e=>e.currentTarget.style.transform="translateY(-2px)"}
      onMouseLeave={e=>e.currentTarget.style.transform="translateY(0)"}>
      <div style={{display:"flex",gap:11,alignItems:"flex-start"}}>
        {/* Avatar */}
        <div style={{width:40,height:40,borderRadius:12,background:`${post.avatarColor}18`,border:`1.5px solid ${post.avatarColor}40`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0,cursor:"default"}}>
          {post.avatar}
        </div>
        <div style={{flex:1,minWidth:0}}>
          <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:6,flexWrap:"wrap"}}>
            <span style={{fontWeight:800,color:C.text,fontSize:14}}>@{post.user}</span>
            {post.badge&&<span style={{background:`${post.avatarColor}15`,color:post.avatarColor,borderRadius:20,padding:"1px 7px",fontSize:10,fontWeight:700}}>{post.badge}</span>}
            <span style={{background:sentBg,color:sentColor,borderRadius:20,padding:"2px 8px",fontSize:10,fontWeight:800}}>{sentLabel}</span>
            {/* Ticker clicable con nombre de empresa */}
            <span onClick={()=>onTickerClick&&onTickerClick(post.ticker)}
              style={{background:C.accentDim,color:C.accent,borderRadius:20,padding:"2px 9px",fontSize:11,fontWeight:700,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:4}}
              title={mainName?`Ver ${mainName} en NexoTrade`:undefined}>
              <span style={{fontFamily:"monospace"}}>${post.ticker}</span>
              {mainName&&<span style={{color:C.muted,fontWeight:500,fontSize:10}}>{mainName}</span>}
            </span>
            <span style={{marginLeft:"auto",fontSize:11,color:C.muted}}>{post.time}</span>
          </div>
          {/* Texto con $TICKERS clicables */}
          <p style={{margin:"0 0 10px",color:C.text,fontSize:13.5,lineHeight:1.65}}>
            {renderBotText(post.text, onTickerClick)}
          </p>
          {post.tags?.length>0&&(
            <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:10}}>
              {post.tags.slice(0,4).map(t=>(
                <span key={t} style={{background:C.accentDim,color:C.muted,borderRadius:20,padding:"2px 8px",fontSize:10}}>#{t}</span>
              ))}
            </div>
          )}
          {/* Botón "Ver análisis completo" */}
          <div style={{display:"flex",gap:12,alignItems:"center",marginTop:4}}>
            <span style={{fontSize:12,color:C.muted}}>❤️ {post.likes}</span>
            <span style={{fontSize:12,color:C.muted}}>💬 {post.comments}</span>
            <span style={{fontSize:12,color:C.muted}}>🔁 {post.reposts}</span>
            <button onClick={()=>onTickerClick&&onTickerClick(post.ticker)}
              style={{marginLeft:"auto",background:`${C.accent}12`,border:`1px solid ${C.accent}30`,borderRadius:20,padding:"3px 12px",fontSize:11,fontWeight:700,color:C.accent,cursor:"pointer"}}>
              {isEN?"View $"+post.ticker+" →":"Ver $"+post.ticker+(mainName?" ("+mainName+")":"")+" →"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function IdeasPage({ isPremium, onNeedPremium }) {
  const [filter, setFilter]     = useState("todos");
  const [sectorF, setSectorF]   = useState("todos");
  const [riskF, setRiskF]       = useState("todos");
  const [sortBy, setSortBy]     = useState("fecha");
  const [livePx, setLivePx]     = useState({});
  const [loading, setLoading]   = useState(true);
  const [selIdea, setSelIdea]   = useState(null);
  const [page, setPage]         = useState(1);
  const PER_PAGE = 12;

  const FINNHUB_KEY = "d86clthr01qgiu44rtmgd86clthr01qgiu44rtn0";

  useEffect(() => {
    const tickers = [...new Set(IDEAS_DATA.map(i => i.ticker))];
    setLoading(true);
    Promise.all(tickers.map(async t => {
      try {
        const r = await fetch(`https://finnhub.io/api/v1/quote?symbol=${t}&token=${FINNHUB_KEY}`);
        const d = await r.json();
        if (d.c > 0) return { t, price: d.c, change: d.dp || 0, prevClose: d.pc || 0 };
      } catch {}
      return null;
    })).then(results => {
      const map = {};
      results.filter(Boolean).forEach(r => { map[r.t] = r; });
      setLivePx(map);
      setLoading(false);
    });
  }, []);

  // No bloqueamos a free — muestran 3 ideas, el resto con blur

  const sectors = ["todos", ...new Set(IDEAS_DATA.map(i => i.sector))];

  const filtered = IDEAS_DATA
    .filter(i => filter === "todos" || i.signal.toLowerCase() === filter)
    .filter(i => sectorF === "todos" || i.sector === sectorF)
    .filter(i => riskF === "todos" || i.riskN === Number(riskF))
    .sort((a, b) => {
      if (sortBy === "upside") {
        const ua = livePx[a.ticker] ? ((a.target - livePx[a.ticker].price) / livePx[a.ticker].price * 100) : ((a.target - a.entry) / a.entry * 100);
        const ub = livePx[b.ticker] ? ((b.target - livePx[b.ticker].price) / livePx[b.ticker].price * 100) : ((b.target - b.entry) / b.entry * 100);
        return ub - ua;
      }
      if (sortBy === "señal") return a.signal.localeCompare(b.signal);
      return new Date(b.published) - new Date(a.published);
    });

  const totalPages = Math.ceil(filtered.length / PER_PAGE);
  const paged = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const compras = IDEAS_DATA.filter(i => i.signal === "COMPRA").length;
  const ventas  = IDEAS_DATA.filter(i => i.signal === "VENTA").length;
  const neutros = IDEAS_DATA.filter(i => i.signal === "NEUTRO").length;

  const SIGNAL_COLOR = { "COMPRA":"#10B981", "VENTA":"#EF4444", "NEUTRO":"#F59E0B" };
  const SIGNAL_BG    = { "COMPRA":"rgba(16,185,129,0.12)", "VENTA":"rgba(239,68,68,0.12)", "NEUTRO":"rgba(245,158,11,0.12)" };
  const SIGNAL_ICON  = { "COMPRA":"↑", "VENTA":"↓", "NEUTRO":"→" };
  const RISK_LABEL   = { 1:"Bajo", 2:"Medio", 3:"Alto" };
  const RISK_COLOR   = { 1:"#10B981", 2:"#F59E0B", 3:"#EF4444" };

  const IdeaCard = ({ idea }) => {
    const live       = livePx[idea.ticker];
    const curPrice   = live?.price || idea.entry;
    const change     = live?.change || 0;
    const isPos      = change >= 0;
    const sc         = SIGNAL_COLOR[idea.signal];
    const isBuy      = idea.signal === "COMPRA";
    const upside     = ((idea.target - curPrice) / curPrice * 100);
    const upsideAbs  = Math.abs(upside).toFixed(1);
    const upsidePos  = (isBuy && upside > 0) || (!isBuy && idea.signal === "VENTA");
    // Progress: where current price is between entry and target
    const lo = Math.min(idea.entry, idea.target, idea.stop);
    const hi = Math.max(idea.entry, idea.target, idea.stop);
    const pctEntry  = ((idea.entry  - lo) / (hi - lo) * 100).toFixed(1);
    const pctTarget = ((idea.target - lo) / (hi - lo) * 100).toFixed(1);
    const pctStop   = ((idea.stop   - lo) / (hi - lo) * 100).toFixed(1);
    const pctCur    = Math.max(0, Math.min(100, ((curPrice - lo) / (hi - lo) * 100))).toFixed(1);
    const daysPub   = Math.floor((new Date() - new Date(idea.published)) / 86400000);

    return (
      <div onClick={() => setSelIdea(idea)}
        style={{background:"linear-gradient(145deg,rgba(10,14,26,0.98),rgba(15,22,40,0.96))",border:`1px solid ${sc}25`,borderRadius:18,overflow:"hidden",cursor:"pointer",transition:"all 0.22s",position:"relative",boxShadow:`0 4px 24px rgba(0,0,0,0.35)`}}
        onMouseEnter={e=>{ e.currentTarget.style.transform="translateY(-3px)"; e.currentTarget.style.boxShadow=`0 16px 40px rgba(0,0,0,0.45),0 0 0 1px ${sc}40`; }}
        onMouseLeave={e=>{ e.currentTarget.style.transform="translateY(0)";   e.currentTarget.style.boxShadow=`0 4px 24px rgba(0,0,0,0.35)`; }}>
        {/* Top accent bar */}
        <div style={{height:3,background:`linear-gradient(90deg,${sc},${sc}30)`}}/>
        <div style={{padding:"14px 16px"}}>
          {/* Row 1: icon + ticker + signal badge */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <div style={{width:36,height:36,borderRadius:10,background:`${sc}18`,border:`1px solid ${sc}30`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:17,flexShrink:0}}>{idea.icon}</div>
              <div>
                <div style={{fontFamily:"monospace",fontWeight:900,fontSize:15,color:sc,letterSpacing:-0.5}}>{idea.ticker}</div>
                <div style={{fontSize:10,color:"#475569",fontWeight:600,maxWidth:130,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{idea.name}</div>
              </div>
            </div>
            <div style={{background:SIGNAL_BG[idea.signal],border:`1px solid ${sc}40`,borderRadius:20,padding:"4px 10px",display:"flex",alignItems:"center",gap:4}}>
              <span style={{fontSize:11,fontWeight:900,color:sc}}>{SIGNAL_ICON[idea.signal]} {idea.signal}</span>
            </div>
          </div>

          {/* Row 2: Current price + change */}
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end",marginBottom:10}}>
            <div>
              <div style={{fontSize:9,color:"#334155",fontWeight:700,letterSpacing:0.6,marginBottom:2}}>PRECIO ACTUAL</div>
              <div style={{fontSize:20,fontWeight:900,color:"#F1F5F9",letterSpacing:-0.5}}>
                ${curPrice.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}
              </div>
              <div style={{fontSize:11,fontWeight:700,color:isPos?"#10B981":"#EF4444"}}>
                {isPos?"▲":"▼"} {Math.abs(change).toFixed(2)}% hoy
              </div>
            </div>
            {/* Upside circle */}
            <div style={{textAlign:"center"}}>
              <div style={{width:56,height:56,borderRadius:"50%",background:`conic-gradient(${sc} ${Math.min(Math.abs(upside),100)*3.6}deg,rgba(255,255,255,0.04) 0deg)`,display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>
                <div style={{width:42,height:42,borderRadius:"50%",background:"rgba(10,14,26,0.97)",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center"}}>
                  <div style={{fontSize:12,fontWeight:900,color:upsidePos?sc:"#EF4444",lineHeight:1}}>{upsidePos?"+":"-"}{upsideAbs}%</div>
                </div>
              </div>
              <div style={{fontSize:8,color:"#334155",fontWeight:700,letterSpacing:0.5,marginTop:2}}>UPSIDE</div>
            </div>
          </div>

          {/* Price track */}
          <div style={{position:"relative",height:6,background:"rgba(255,255,255,0.05)",borderRadius:4,marginBottom:6}}>
            {/* Stop */}
            <div style={{position:"absolute",left:`${pctStop}%`,top:-2,width:2,height:10,background:"#EF4444",borderRadius:2}}/>
            {/* Entry */}
            <div style={{position:"absolute",left:`${pctEntry}%`,top:-2,width:2,height:10,background:"#F59E0B",borderRadius:2}}/>
            {/* Target */}
            <div style={{position:"absolute",left:`${Math.min(parseFloat(pctTarget),98)}%`,top:-2,width:2,height:10,background:sc,borderRadius:2}}/>
            {/* Current position dot */}
            <div style={{position:"absolute",left:`${pctCur}%`,top:-3,width:12,height:12,borderRadius:"50%",background:sc,boxShadow:`0 0 6px ${sc}`,transform:"translateX(-6px)",border:"2px solid rgba(10,14,26,0.9)"}}/>
          </div>
          <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}>
            <div style={{fontSize:9,color:"#EF4444"}}>Stop ${idea.stop}</div>
            <div style={{fontSize:9,color:"#F59E0B"}}>Entrada ${idea.entry}</div>
            <div style={{fontSize:9,color:sc}}>Obj. ${idea.target}</div>
          </div>

          {/* Tags row */}
          <div style={{display:"flex",gap:4,flexWrap:"wrap",marginBottom:10}}>
            {idea.tags.slice(0,3).map(tag=>(
              <span key={tag} style={{background:"rgba(255,255,255,0.04)",border:"1px solid rgba(255,255,255,0.08)",borderRadius:5,padding:"2px 7px",fontSize:9,color:"#64748B",fontWeight:700}}>{tag}</span>
            ))}
          </div>

          {/* Bottom row: horizon + risk + days */}
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",borderTop:"1px solid rgba(255,255,255,0.05)",paddingTop:8}}>
            <div style={{display:"flex",gap:6}}>
              <span style={{background:"rgba(99,102,241,0.1)",border:"1px solid rgba(99,102,241,0.2)",borderRadius:5,padding:"2px 7px",fontSize:9,color:"#818CF8",fontWeight:700}}>⏱ {idea.horizon}</span>
              <span style={{background:`rgba(${RISK_COLOR[idea.riskN]==="#10B981"?"16,185,129":RISK_COLOR[idea.riskN]==="#F59E0B"?"245,158,11":"239,68,68"},0.1)`,borderRadius:5,padding:"2px 7px",fontSize:9,color:RISK_COLOR[idea.riskN],fontWeight:700}}>
                ⚡ Riesgo {RISK_LABEL[idea.riskN]}
              </span>
            </div>
            <span style={{fontSize:9,color:"#334155"}}>{daysPub === 0 ? "Hoy" : `Hace ${daysPub}d`}</span>
          </div>
        </div>
      </div>
    );
  };

  // ── MODAL DETAIL ──
  const ModalDetail = ({ idea, onClose }) => {
    if (!idea) return null;
    const live     = livePx[idea.ticker];
    const curPrice = live?.price || idea.entry;
    const change   = live?.change || 0;
    const isPos    = change >= 0;
    const sc       = SIGNAL_COLOR[idea.signal];
    const upside   = ((idea.target - curPrice) / curPrice * 100);
    const rr       = Math.abs(idea.target - idea.entry) / Math.abs(idea.entry - idea.stop);

    return (
      <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.7)",backdropFilter:"blur(8px)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
        <div onClick={e=>e.stopPropagation()}
          style={{background:"linear-gradient(145deg,rgba(10,14,26,0.99),rgba(15,22,40,0.97))",border:`1px solid ${sc}30`,borderRadius:22,padding:0,maxWidth:580,width:"100%",maxHeight:"90vh",overflow:"auto",boxShadow:`0 32px 80px rgba(0,0,0,0.7),0 0 0 1px ${sc}20`}}>
          {/* Top bar */}
          <div style={{height:4,background:`linear-gradient(90deg,${sc},${sc}40,transparent)`}}/>
          <div style={{padding:"20px 24px"}}>
            {/* Header */}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:18}}>
              <div style={{display:"flex",gap:12,alignItems:"center"}}>
                <div style={{width:52,height:52,borderRadius:14,background:`${sc}18`,border:`1px solid ${sc}30`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24}}>{idea.icon}</div>
                <div>
                  <div style={{fontFamily:"monospace",fontWeight:900,fontSize:22,color:sc}}>{idea.ticker}</div>
                  <div style={{fontSize:13,color:"#64748B",fontWeight:600}}>{idea.name}</div>
                  <div style={{fontSize:11,color:"#334155"}}>{idea.sector}</div>
                </div>
              </div>
              <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:6}}>
                <div style={{background:SIGNAL_BG[idea.signal],border:`1px solid ${sc}40`,borderRadius:20,padding:"5px 14px"}}>
                  <span style={{fontSize:13,fontWeight:900,color:sc}}>{SIGNAL_ICON[idea.signal]} {idea.signal}</span>
                </div>
                <button onClick={onClose} style={{background:"transparent",border:"none",color:"#475569",cursor:"pointer",fontSize:18,padding:"2px 6px"}}>✕</button>
              </div>
            </div>

            {/* Price stats grid */}
            <div className="nexo-idea-price-stats" style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10,marginBottom:18}}>
              {[
                {l:"PRECIO ACTUAL", v:`$${curPrice.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}`, sub:`${isPos?"▲":"▼"} ${Math.abs(change).toFixed(2)}% hoy`, sc2:isPos?"#10B981":"#EF4444"},
                {l:"PRECIO OBJETIVO", v:`$${idea.target}`, sub:`${upside >= 0?"+":""}${upside.toFixed(1)}% upside`, sc2:upside>=0?"#10B981":"#EF4444"},
                {l:"STOP LOSS", v:`$${idea.stop}`, sub:`R:R ${rr.toFixed(1)}:1`, sc2:"#EF4444"},
              ].map(s=>(
                <div key={s.l} style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.07)",borderRadius:12,padding:"12px 14px"}}>
                  <div style={{fontSize:9,color:"#334155",fontWeight:700,letterSpacing:0.6,marginBottom:4}}>{s.l}</div>
                  <div style={{fontSize:18,fontWeight:900,color:"#F1F5F9",marginBottom:2}}>{s.v}</div>
                  <div style={{fontSize:11,fontWeight:700,color:s.sc2}}>{s.sub}</div>
                </div>
              ))}
            </div>

            {/* More metadata */}
            <div className="nexo-idea-meta-stats" style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:18}}>
              {[
                {l:"ENTRADA SUGERIDA", v:`$${idea.entry}`},
                {l:"HORIZONTE", v:idea.horizon},
                {l:"RIESGO", v:RISK_LABEL[idea.riskN], c:RISK_COLOR[idea.riskN]},
              ].map(s=>(
                <div key={s.l} style={{background:"rgba(255,255,255,0.02)",border:"1px solid rgba(255,255,255,0.05)",borderRadius:10,padding:"10px 12px",textAlign:"center"}}>
                  <div style={{fontSize:9,color:"#334155",fontWeight:700,letterSpacing:0.6,marginBottom:4}}>{s.l}</div>
                  <div style={{fontSize:14,fontWeight:800,color:s.c||"#F1F5F9"}}>{s.v}</div>
                </div>
              ))}
            </div>

            {/* Tags */}
            <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:16}}>
              {idea.tags.map(tag=>(
                <span key={tag} style={{background:`${sc}15`,border:`1px solid ${sc}30`,borderRadius:6,padding:"4px 10px",fontSize:11,color:sc,fontWeight:700}}>{tag}</span>
              ))}
            </div>

            {/* Thesis */}
            <div style={{background:"rgba(255,255,255,0.02)",border:"1px solid rgba(255,255,255,0.06)",borderRadius:14,padding:"16px 18px",marginBottom:14}}>
              <div style={{fontSize:11,color:"#475569",fontWeight:700,letterSpacing:0.5,marginBottom:8}}>📝 TESIS DE INVERSIÓN</div>
              <div style={{fontSize:13,color:"#CBD5E1",lineHeight:1.75}}>{idea.thesis}</div>
            </div>

            {/* Footer */}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",fontSize:11,color:"#334155"}}>
              <span>Publicado: {new Date(idea.published).toLocaleDateString("es-ES",{day:"2-digit",month:"short",year:"numeric"})}</span>
              <span>{idea.analyst}</span>
              <span style={{color:"#1E293B",fontSize:10}}>⚠️ No es consejo financiero</span>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div style={{maxWidth:1100,margin:"0 auto"}}>
      {/* ── HEADER ── */}
      <div style={{background:"linear-gradient(135deg,rgba(10,14,26,0.98),rgba(20,26,46,0.95))",border:"1px solid rgba(99,102,241,0.2)",borderRadius:20,padding:"18px 24px",marginBottom:16,position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",top:-40,right:-40,width:200,height:200,background:"radial-gradient(circle,rgba(99,102,241,0.1) 0%,transparent 70%)",pointerEvents:"none"}}/>
        <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
          <span style={{fontSize:28}}>💡</span>
          <div>
            <div style={{fontSize:19,fontWeight:900,color:"#F1F5F9",letterSpacing:-0.5}}>Ideas de Inversión</div>
            <div style={{fontSize:12,color:"#475569"}}>Señales analizadas por NexoTrade Research · Precios en tiempo real · {IDEAS_DATA.length} ideas activas</div>
          </div>
          <div style={{marginLeft:"auto",display:"flex",gap:8,flexWrap:"wrap"}}>
            {[{l:`${compras} Compras`,c:"#10B981",bg:"rgba(16,185,129,0.1)"},{l:`${ventas} Ventas`,c:"#EF4444",bg:"rgba(239,68,68,0.1)"},{l:`${neutros} Neutro`,c:"#F59E0B",bg:"rgba(245,158,11,0.1)"}].map(s=>(
              <div key={s.l} style={{background:s.bg,border:`1px solid ${s.c}30`,borderRadius:20,padding:"5px 12px",fontSize:11,fontWeight:800,color:s.c}}>{s.l}</div>
            ))}
            {loading && <div style={{background:"rgba(99,102,241,0.1)",border:"1px solid rgba(99,102,241,0.3)",borderRadius:20,padding:"5px 12px",fontSize:11,fontWeight:700,color:"#818CF8"}}>⟳ Cargando precios…</div>}
          </div>
        </div>
      </div>

      {/* ── FILTERS ── */}
      <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:14,alignItems:"center"}}>
        {/* Signal filter */}
        <div style={{display:"flex",gap:4}}>
          {[["todos","🌐 Todos"],["compra","↑ Compras"],["venta","↓ Ventas"],["neutro","→ Neutro"]].map(([k,l])=>(
            <button key={k} onClick={()=>{setFilter(k);setPage(1);}}
              style={{background:filter===k?"linear-gradient(135deg,#6366F1,#4F46E5)":"transparent",border:`1.5px solid ${filter===k?"transparent":C.border}`,borderRadius:20,padding:"6px 13px",fontSize:11,fontWeight:700,color:filter===k?"#fff":C.muted,cursor:"pointer",transition:"all 0.15s"}}>
              {l}
            </button>
          ))}
        </div>
        <div style={{width:1,height:24,background:C.border}}/>
        {/* Risk filter */}
        {[["todos","⚡ Todo riesgo"],["1","🟢 Bajo"],["2","🟡 Medio"],["3","🔴 Alto"]].map(([k,l])=>(
          <button key={k} onClick={()=>{setRiskF(k);setPage(1);}}
            style={{background:riskF===k?"rgba(99,102,241,0.2)":"transparent",border:`1.5px solid ${riskF===k?"#6366F1":C.border}`,borderRadius:20,padding:"6px 12px",fontSize:11,fontWeight:700,color:riskF===k?"#A5B4FC":C.muted,cursor:"pointer",transition:"all 0.15s"}}>
            {l}
          </button>
        ))}
        {/* Sort */}
        <div style={{marginLeft:"auto"}}>
          <select value={sortBy} onChange={e=>{setSortBy(e.target.value);setPage(1);}}
            style={{background:"rgba(255,255,255,0.04)",border:`1px solid ${C.border}`,borderRadius:10,padding:"6px 12px",fontSize:12,color:C.muted,cursor:"pointer"}}>
            <option value="fecha">Más recientes</option>
            <option value="upside">Mayor upside</option>
            <option value="señal">Por señal</option>
          </select>
        </div>
      </div>

      {/* ── IDEA CARDS GRID ── */}
      <div style={{position:"relative"}}>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(310px,1fr))",gap:14,marginBottom:20}}>
          {paged.map((idea, idx) => {
            const isLocked = !isPremium && idx >= 3;
            return (
              <div key={idea.id} style={{position:"relative",userSelect:isLocked?"none":"auto"}}>
                <div style={{filter:isLocked?"blur(6px)":"none",pointerEvents:isLocked?"none":"auto",transition:"filter 0.2s"}}>
                  <IdeaCard idea={idea}/>
                </div>
                {isLocked && idx === 3 && (
                  <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",background:"rgba(10,14,26,0.3)",borderRadius:18,backdropFilter:"blur(2px)",zIndex:2}}>
                    <div style={{background:"rgba(12,10,30,0.97)",border:"1px solid rgba(217,119,6,0.4)",borderRadius:16,padding:"20px 24px",textAlign:"center",maxWidth:240,boxShadow:"0 8px 40px rgba(0,0,0,0.6)"}}>
                      <div style={{fontSize:28,marginBottom:8}}>🔒</div>
                      <div style={{fontWeight:800,color:"#fff",fontSize:14,marginBottom:6}}>+{filtered.length - 3} ideas bloqueadas</div>
                      <div style={{fontSize:12,color:"#94a3b8",marginBottom:14}}>Hazte PREMIUM para ver todas las señales, tesis y precios objetivo</div>
                      <button onClick={onNeedPremium}
                        style={{background:"linear-gradient(135deg,#D97706,#6366F1)",color:"#fff",border:"none",borderRadius:10,padding:"10px 20px",fontSize:13,fontWeight:800,cursor:"pointer",width:"100%"}}>
                        ✦ Ver todas — $9.99/mes
                      </button>
                      <div style={{fontSize:10,color:"#475569",marginTop:6}}>7 días gratis · Cancela cuando quieras</div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
        {/* Banner debajo si hay más páginas y es free */}
        {!isPremium && page === 1 && (
          <div style={{background:"linear-gradient(135deg,rgba(217,119,6,0.12),rgba(99,102,241,0.08))",border:"1px solid rgba(217,119,6,0.25)",borderRadius:16,padding:"20px 24px",marginTop:4,marginBottom:20,textAlign:"center"}}>
            <div style={{fontWeight:800,color:"#FCD34D",fontSize:15,marginBottom:6}}>✦ Desbloquea {IDEAS_DATA.length - 3} ideas más con PREMIUM</div>
            <div style={{fontSize:13,color:"#64748b",marginBottom:14}}>Señales de compra/venta, tesis completa, precio objetivo y stop loss actualizado en tiempo real</div>
            <button onClick={onNeedPremium}
              style={{background:"linear-gradient(135deg,#D97706,#6366F1)",color:"#fff",border:"none",borderRadius:10,padding:"12px 32px",fontSize:14,fontWeight:800,cursor:"pointer",boxShadow:"0 4px 20px rgba(217,119,6,0.4)"}}>
              ✦ Activar PREMIUM — 7 días gratis →
            </button>
          </div>
        )}
      </div>
      {filtered.length === 0 && (
        <div style={{textAlign:"center",padding:"40px 0",color:C.muted}}>No hay ideas con esos filtros</div>
      )}

      {/* ── PAGINATION ── */}
      {totalPages > 1 && (
        <div style={{display:"flex",justifyContent:"center",gap:8,marginBottom:20}}>
          {Array.from({length:totalPages},(_,i)=>i+1).map(n=>(
            <button key={n} onClick={()=>setPage(n)}
              style={{width:34,height:34,borderRadius:8,border:`1.5px solid ${page===n?"#6366F1":C.border}`,background:page===n?"linear-gradient(135deg,#6366F1,#4F46E5)":"transparent",color:page===n?"#fff":C.muted,fontWeight:700,fontSize:13,cursor:"pointer"}}>
              {n}
            </button>
          ))}
        </div>
      )}

      <div style={{textAlign:"center",padding:"8px 0 16px",fontSize:10,color:"#1E293B"}}>
        ⚠️ Las ideas son análisis informativos del equipo NexoTrade. No constituyen consejo financiero. Invierte con responsabilidad.
      </div>

      {/* Modal */}
      {selIdea && <ModalDetail idea={selIdea} onClose={()=>setSelIdea(null)}/>}
    </div>
  );
}

// ── MENSAJES PRIVADOS PAGE ────────────────────────────────────────────────────
function MessagesPage({ user, following, supabaseClient, onNeedAuth, initialChat }) {
  const [conversations, setConversations] = useState([]);  // {userId, username, avatar, avatarColor, lastMsg, unread, isMutual}
  const [selConv, setSelConv]   = useState(initialChat || null); // {id, username, avatar, avatarColor}
  const [messages, setMessages] = useState([]);
  const [msgText, setMsgText]   = useState("");
  const [sending, setSending]   = useState(false);
  const [loading, setLoading]   = useState(true);
  const [mutuals, setMutuals]   = useState([]); // IDs de seguidores mutuos
  const [search, setSearch]     = useState("");
  const [newDM, setNewDM]       = useState(false);
  const [allFollowers, setAllFollowers] = useState([]);
  const msgEndRef = useRef(null);

  const FINNHUB_KEY = "d86clthr01qgiu44rtmgd86clthr01qgiu44rtn0";
  const sb = supabaseClient || supabase;

  // Cargar seguidores mutuos y conversaciones
  useEffect(() => {
    if (!user?.id || user.id === "local") { setLoading(false); return; }
    // Fallback: always stop loading after 4s max
    const timeout = setTimeout(() => setLoading(false), 4000);
    const init = async () => {
      try {
        // Quién me sigue a mí
        const { data: followers } = await sb.from("follows")
          .select("follower_id").eq("following_id", user.id);
        const followerIds = (followers||[]).map(f => f.follower_id);

        // A quién sigo yo
        const { data: iFollow } = await sb.from("follows")
          .select("following_id").eq("follower_id", user.id);
        const iFollowIds = (iFollow||[]).map(f => f.following_id);

        // Mutuos = los que me siguen Y yo sigo
        const mutualIds = followerIds.filter(id => iFollowIds.includes(id));
        setMutuals(mutualIds);

        // Obtener perfiles de mutuos
        if (mutualIds.length > 0) {
          const { data: profiles } = await sb.from("profiles")
            .select("id,username,avatar_emoji,avatar_color")
            .in("id", mutualIds);
          setAllFollowers(profiles || []);
        }

        // Cargar mensajes existentes (tabla puede no existir aún)
        try {
          const { data: msgs } = await sb.from("direct_messages")
            .select("*")
            .or(`sender_id.eq.${user.id},receiver_id.eq.${user.id}`)
            .order("created_at", { ascending: false })
            .limit(100);
          if (msgs && msgs.length > 0) {
            const convMap = {};
            msgs.forEach(m => {
              const otherId = m.sender_id === user.id ? m.receiver_id : m.sender_id;
              if (!convMap[otherId]) convMap[otherId] = [];
              convMap[otherId].push(m);
            });
            const convList = Object.entries(convMap).map(([uid, ms]) => {
              const last = ms[0];
              return { userId: uid, lastMsg: last.content, lastTime: last.created_at, isMutual: mutualIds.includes(uid) };
            });
            setConversations(convList);
          }
        } catch(e2) { /* tabla direct_messages no existe aún */ }
      } catch(e) { console.error(e); }
      finally { clearTimeout(timeout); setLoading(false); }
    };
    init();
    return () => clearTimeout(timeout);
  }, [user?.id]);

  // Cargar mensajes de la conversación seleccionada
  useEffect(() => {
    if (!selConv || !user?.id) return;
    const load = async () => {
      try {
        const { data } = await sb.from("direct_messages")
          .select("*")
          .or(`and(sender_id.eq.${user.id},receiver_id.eq.${selConv.id}),and(sender_id.eq.${selConv.id},receiver_id.eq.${user.id})`)
          .order("created_at", { ascending: true })
          .limit(100);
        setMessages(data || []);
        setTimeout(() => msgEndRef.current?.scrollIntoView({ behavior: "smooth" }), 100);
      } catch(e) {}
    };
    load();
    // Poll cada 5s
    const iv = setInterval(load, 5000);
    return () => clearInterval(iv);
  }, [selConv?.id, user?.id]);

  useEffect(() => {
    msgEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const isMutualWith = (uid) => mutuals.includes(uid);

  const sendMessage = async () => {
    if (!msgText.trim() || sending || !selConv || !user?.id) return;
    if (!isMutualWith(selConv.id)) return;
    setSending(true);
    try {
      const { data, error } = await sb.from("direct_messages").insert({
        sender_id: user.id,
        receiver_id: selConv.id,
        content: msgText.trim(),
      }).select().single();
      if (!error && data) {
        setMessages(prev => [...prev, data]);
        setMsgText("");
        setTimeout(() => msgEndRef.current?.scrollIntoView({ behavior: "smooth" }), 50);
      }
    } catch(e) {}
    setSending(false);
  };

  if (!user || user.id === "local") {
    return (
      <div style={{maxWidth:480,margin:"80px auto",textAlign:"center",padding:"0 20px"}}>
        <div style={{fontSize:64,marginBottom:16}}>💬</div>
        <div style={{fontSize:22,fontWeight:900,color:C.text,marginBottom:8}}>Mensajes Privados</div>
        <div style={{fontSize:14,color:C.muted,marginBottom:24}}>Inicia sesión para ver y enviar mensajes privados.</div>
        <button onClick={onNeedAuth} style={{background:"linear-gradient(135deg,#F59E0B,#B45309)",color:"#fff",border:"none",borderRadius:12,padding:"12px 32px",fontSize:15,fontWeight:800,cursor:"pointer"}}>
          Iniciar sesión
        </button>
      </div>
    );
  }

  const filteredMutualsForNew = allFollowers.filter(p =>
    !search || p.username?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="nexo-messages-wrapper" style={{maxWidth:920,margin:"0 auto",height:"calc(100vh - 130px)",display:"flex",flexDirection:"column",gap:0}}>
      {/* Header */}
      <div style={{background:"linear-gradient(135deg,rgba(139,92,246,0.15),rgba(180,83,9,0.08))",border:"1px solid rgba(139,92,246,0.25)",borderRadius:"18px 18px 0 0",padding:"14px 20px",display:"flex",alignItems:"center",gap:12,borderBottom:"none"}}>
        <div style={{width:40,height:40,borderRadius:12,background:"linear-gradient(135deg,#F59E0B,#B45309)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>💬</div>
        <div>
          <div style={{fontSize:16,fontWeight:900,color:C.text,letterSpacing:"-0.3px"}}>Mensajes Privados</div>
          <div style={{fontSize:11,color:C.muted,marginTop:1}}>
            {mutuals.length > 0
              ? <span><span style={{color:"#10B981",fontWeight:700}}>{mutuals.length}</span> conexión{mutuals.length!==1?"es":""} mutua{mutuals.length!==1?"s":""}</span>
              : "Solo entre usuarios que se siguen mutuamente"}
          </div>
        </div>
        <button onClick={()=>{setNewDM(true);setSelConv(null);}}
          style={{marginLeft:"auto",background:"linear-gradient(135deg,#F59E0B,#B45309)",border:"none",borderRadius:20,padding:"8px 18px",fontSize:12,fontWeight:800,color:"#fff",cursor:"pointer",display:"flex",alignItems:"center",gap:6,boxShadow:"0 2px 12px rgba(139,92,246,0.35)",whiteSpace:"nowrap"}}>
          ✏️ <span className="nexo-msg-btn-text">Nuevo mensaje</span>
        </button>
      </div>

      <div className="nexo-messages-grid" style={{display:"grid",gridTemplateColumns:"300px 1fr",flex:1,minHeight:0,border:`1px solid rgba(139,92,246,0.2)`,borderRadius:"0 0 18px 18px",overflow:"hidden"}}>
        {/* ── LISTA DE CONVERSACIONES ── */}
        <div className="nexo-messages-list" style={{background:C.card,borderRight:`1px solid rgba(139,92,246,0.15)`,overflow:"auto",display:"flex",flexDirection:"column"}}>
          {/* Search */}
          <div style={{padding:"10px 12px",borderBottom:`1px solid rgba(139,92,246,0.1)`,background:"rgba(139,92,246,0.04)"}}>
            <div style={{position:"relative"}}>
              <svg style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",opacity:0.4}} width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
              <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar conversación…"
                style={{width:"100%",background:"rgba(255,255,255,0.05)",border:`1px solid rgba(139,92,246,0.2)`,borderRadius:20,padding:"7px 10px 7px 28px",fontSize:12,color:C.text,outline:"none",boxSizing:"border-box",fontFamily:"inherit"}}/>
            </div>
          </div>

          {loading && (
            <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:8,padding:24,color:C.muted}}>
              <div style={{width:28,height:28,borderRadius:"50%",border:"2px solid rgba(139,92,246,0.3)",borderTopColor:"#F59E0B",animation:"spin 1s linear infinite"}}/>
              <span style={{fontSize:12}}>Cargando…</span>
            </div>
          )}

          {!loading && mutuals.length === 0 && (
            <div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"20px 16px",textAlign:"center"}}>
              <div style={{width:52,height:52,borderRadius:16,background:"rgba(139,92,246,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,marginBottom:12}}>👥</div>
              <div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:6}}>Sin conexiones aún</div>
              <div style={{fontSize:12,color:C.muted,lineHeight:1.6}}>Sigue a alguien y espera que te siga de vuelta para poder chatear.</div>
            </div>
          )}

          {/* Mutuales disponibles para chatear */}
          <div style={{overflowY:"auto",flex:1}}>
            {allFollowers.filter(p => !search || p.username?.toLowerCase().includes(search.toLowerCase())).map(prof => {
              const conv = conversations.find(c => c.userId === prof.id);
              const isSelected = selConv?.id === prof.id;
              return (
                <div key={prof.id} onClick={()=>{setSelConv({id:prof.id,username:prof.username,avatar:prof.avatar_emoji||"👤",avatarColor:prof.avatar_color||C.accent});setNewDM(false);}}
                  style={{display:"flex",gap:10,alignItems:"center",padding:"11px 14px",cursor:"pointer",background:isSelected?"rgba(139,92,246,0.13)":"transparent",borderLeft:`3px solid ${isSelected?"#F59E0B":"transparent"}`,transition:"all 0.15s",position:"relative"}}
                  onMouseEnter={e=>{ if(!isSelected){e.currentTarget.style.background="rgba(255,255,255,0.04)";} }}
                  onMouseLeave={e=>{ if(!isSelected){e.currentTarget.style.background="transparent";} }}>
                  {/* Avatar */}
                  <div style={{width:40,height:40,borderRadius:"50%",background:prof.avatar_color||C.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:19,flexShrink:0,border:isSelected?"2px solid rgba(139,92,246,0.5)":"2px solid transparent",transition:"border 0.15s"}}>
                    {prof.avatar_emoji||"👤"}
                  </div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontWeight:700,color:isSelected?"#FCD34D":C.text,fontSize:13,marginBottom:2}}>{prof.username}</div>
                    <div style={{fontSize:11,color:C.muted2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{conv?.lastMsg || <span style={{color:"rgba(139,92,246,0.6)",fontStyle:"italic"}}>Iniciar conversación…</span>}</div>
                  </div>
                  {/* Online dot (decorativo) */}
                  <div style={{width:8,height:8,borderRadius:"50%",background:"#10B981",flexShrink:0,opacity:0.7}}/>
                </div>
              );
            })}
          </div>
        </div>

        {/* ── PANEL DE CHAT ── */}
        <div className="nexo-messages-chat" style={{background:C.bg||"#0a0e1a",display:"flex",flexDirection:"column",overflow:"hidden"}}>
          {/* ── NUEVO MENSAJE UI ── */}
          {newDM && !selConv && (
            <div style={{flex:1,overflow:"auto",padding:"20px 24px"}}>
              <div style={{fontWeight:900,color:C.text,fontSize:16,marginBottom:4,letterSpacing:"-0.3px"}}>✏️ Nuevo mensaje</div>
              <div style={{fontSize:12,color:C.muted,marginBottom:20}}>Solo puedes escribir a usuarios que también te siguen a ti.</div>
              {filteredMutualsForNew.length === 0 && (
                <div style={{textAlign:"center",padding:"32px 24px",background:"rgba(139,92,246,0.04)",borderRadius:16,border:"1px dashed rgba(139,92,246,0.2)"}}>
                  <div style={{fontSize:36,marginBottom:10}}>🔒</div>
                  <div style={{fontWeight:700,color:C.text,fontSize:14,marginBottom:6}}>Sin conexiones mutuas</div>
                  <div style={{fontSize:12,color:C.muted,lineHeight:1.7}}>Sigue a alguien y espera que te sigan de vuelta para poder chatear.</div>
                </div>
              )}
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {filteredMutualsForNew.map(prof => (
                  <div key={prof.id} onClick={()=>{setSelConv({id:prof.id,username:prof.username,avatar:prof.avatar_emoji||"👤",avatarColor:prof.avatar_color||C.accent});setNewDM(false);}}
                    style={{display:"flex",gap:12,alignItems:"center",padding:"12px 16px",background:"rgba(255,255,255,0.03)",border:"1px solid rgba(139,92,246,0.15)",borderRadius:14,cursor:"pointer",transition:"all 0.15s"}}
                    onMouseEnter={e=>{e.currentTarget.style.background="rgba(139,92,246,0.08)";e.currentTarget.style.borderColor="rgba(139,92,246,0.3)";}}
                    onMouseLeave={e=>{e.currentTarget.style.background="rgba(255,255,255,0.03)";e.currentTarget.style.borderColor="rgba(139,92,246,0.15)";}}>
                    <div style={{width:44,height:44,borderRadius:"50%",background:prof.avatar_color||C.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}>{prof.avatar_emoji||"👤"}</div>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontWeight:700,color:C.text,fontSize:14}}>{prof.username}</div>
                      <div style={{fontSize:11,color:"#10B981",marginTop:2}}>✓ Seguidor mutuo — Puedes enviarle mensajes</div>
                    </div>
                    <div style={{color:"#F59E0B",fontSize:18,opacity:0.8}}>→</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ── CHAT ABIERTO ── */}
          {selConv && (
            <>
              {/* Chat header */}
              <div style={{padding:"12px 18px",borderBottom:"1px solid rgba(139,92,246,0.15)",display:"flex",alignItems:"center",gap:12,background:"rgba(139,92,246,0.05)"}}>
                <div style={{position:"relative"}}>
                  <div style={{width:38,height:38,borderRadius:"50%",background:selConv.avatarColor||C.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:19}}>{selConv.avatar||"👤"}</div>
                  <div style={{position:"absolute",bottom:0,right:0,width:10,height:10,borderRadius:"50%",background:"#10B981",border:"2px solid #0a0e1a"}}/>
                </div>
                <div>
                  <div style={{fontWeight:800,color:C.text,fontSize:14,letterSpacing:"-0.2px"}}>@{selConv.username}</div>
                  <div style={{fontSize:10,color:"#10B981",marginTop:1}}>● En línea · Chat privado cifrado</div>
                </div>
                <button onClick={()=>setSelConv(null)} style={{marginLeft:"auto",background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.08)",borderRadius:8,color:C.muted,cursor:"pointer",fontSize:14,padding:"4px 8px",lineHeight:1}}>✕</button>
              </div>

              {/* Check mutual */}
              {!isMutualWith(selConv.id) && (
                <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:12,padding:24}}>
                  <div style={{fontSize:48}}>🔒</div>
                  <div style={{fontWeight:800,color:C.text,fontSize:16,textAlign:"center"}}>Chat bloqueado</div>
                  <div style={{fontSize:13,color:C.muted,textAlign:"center",maxWidth:320,lineHeight:1.7}}>
                    Para chatear con <strong>{selConv.username}</strong>, ambos tienen que seguirse mutuamente. Sigue al usuario y espera que te siga de vuelta.
                  </div>
                </div>
              )}

              {/* Messages area */}
              {isMutualWith(selConv.id) && (
                <>
                  <div style={{flex:1,overflow:"auto",padding:"16px",display:"flex",flexDirection:"column",gap:8}}>
                    {messages.length === 0 && (
                      <div style={{textAlign:"center",color:C.muted,padding:"40px 0",fontSize:13}}>
                        <div style={{fontSize:36,marginBottom:8}}>👋</div>
                        Sé el primero en escribir. Esta conversación es privada.
                      </div>
                    )}
                    {messages.map((m,i) => {
                      const isMine = m.sender_id === user.id;
                      const time = new Date(m.created_at).toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"});
                      return (
                        <div key={m.id||i} style={{display:"flex",justifyContent:isMine?"flex-end":"flex-start"}}>
                          <div style={{maxWidth:"72%",background:isMine?"linear-gradient(135deg,#F59E0B,#B45309)":"rgba(255,255,255,0.06)",borderRadius:isMine?"16px 16px 4px 16px":"16px 16px 16px 4px",padding:"8px 13px",border:isMine?"none":`1px solid ${C.border}`}}>
                            <div style={{fontSize:13,color:isMine?"#fff":C.text,lineHeight:1.5,wordBreak:"break-word"}}>{m.content}</div>
                            <div style={{fontSize:10,color:isMine?"rgba(255,255,255,0.5)":C.muted2,marginTop:3,textAlign:"right"}}>{time}</div>
                          </div>
                        </div>
                      );
                    })}
                    <div ref={msgEndRef}/>
                  </div>

                  {/* Input */}
                  <div style={{padding:"10px 14px",borderTop:"1px solid rgba(139,92,246,0.15)",display:"flex",gap:8,alignItems:"center",background:"rgba(139,92,246,0.03)"}}>
                    <input value={msgText} onChange={e=>setMsgText(e.target.value)}
                      onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendMessage();}}}
                      placeholder={`Escribe a @${selConv.username}…`}
                      maxLength={500}
                      style={{flex:1,background:"rgba(255,255,255,0.06)",border:"1px solid rgba(139,92,246,0.2)",borderRadius:22,padding:"10px 18px",fontSize:13,color:C.text,outline:"none",fontFamily:"inherit",transition:"border 0.15s"}}
                      onFocus={e=>e.target.style.borderColor="rgba(139,92,246,0.5)"}
                      onBlur={e=>e.target.style.borderColor="rgba(139,92,246,0.2)"}
                    />
                    <button onClick={sendMessage} disabled={!msgText.trim()||sending}
                      style={{background:msgText.trim()&&!sending?"linear-gradient(135deg,#F59E0B,#B45309)":"rgba(139,92,246,0.2)",border:"none",borderRadius:22,padding:"10px 18px",fontSize:13,fontWeight:800,color:msgText.trim()&&!sending?"#fff":"rgba(139,92,246,0.5)",cursor:msgText.trim()&&!sending?"pointer":"not-allowed",whiteSpace:"nowrap",transition:"all 0.2s",boxShadow:msgText.trim()&&!sending?"0 2px 12px rgba(139,92,246,0.35)":"none"}}>
                      {sending?"…":"Enviar ↗"}
                    </button>
                  </div>
                </>
              )}
            </>
          )}

          {/* Estado vacío */}
          {!selConv && !newDM && (
            <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:14,padding:"0 20px"}}>
              {/* Ilustración */}
              <div style={{position:"relative",marginBottom:4}}>
                <div style={{width:72,height:72,borderRadius:22,background:"linear-gradient(135deg,rgba(139,92,246,0.15),rgba(180,83,9,0.08))",border:"1px solid rgba(139,92,246,0.2)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:34}}>💬</div>
                <div style={{position:"absolute",top:-6,right:-6,width:22,height:22,borderRadius:"50%",background:"linear-gradient(135deg,#F59E0B,#B45309)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,color:"#fff",fontWeight:800,boxShadow:"0 2px 8px rgba(139,92,246,0.5)"}}>
                  {mutuals.length}
                </div>
              </div>
              <div>
                <div style={{fontWeight:900,color:C.text,fontSize:17,textAlign:"center",letterSpacing:"-0.4px",marginBottom:6}}>Tus mensajes privados</div>
                <div style={{fontSize:13,color:C.muted,textAlign:"center",maxWidth:260,lineHeight:1.7}}>
                  Selecciona una conversación o empieza una nueva. Solo con seguidores mutuos.
                </div>
              </div>
              <button onClick={()=>setNewDM(true)}
                style={{background:"linear-gradient(135deg,#F59E0B,#B45309)",border:"none",borderRadius:14,padding:"11px 28px",fontSize:13,fontWeight:800,color:"#fff",cursor:"pointer",boxShadow:"0 4px 16px rgba(139,92,246,0.4)",transition:"transform 0.15s,box-shadow 0.15s"}}
                onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 6px 20px rgba(139,92,246,0.5)";}}
                onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="0 4px 16px rgba(139,92,246,0.4)";}}>
                ✏️ Nuevo mensaje
              </button>
            </div>
          )}
        </div>
      </div>

    </div>
  );
}


// ── CRYPTO PERFORMANCE PAGE (page 2) — Heatmap estilo Finviz ──────────────────
function CryptoPerformancePage({ lang="es" }) {
  const isEN = lang==="en";
  const [coins, setCoins]         = useState([]);
  const [global, setGlobal]       = useState(null);
  const [fearGreed, setFearGreed] = useState(null);
  const [loading, setLoading]     = useState(true);
  const [err, setErr]             = useState(null);
  const [period, setPeriod]       = useState("24h");
  const [view, setView]           = useState("heatmap");
  const [search, setSearch]       = useState("");
  const [countdown, setCountdown] = useState(60);
  const [lastUpdate, setLastUpdate] = useState(null);
  const [sortCol, setSortCol]     = useState("market_cap");
  const [sortAsc, setSortAsc]     = useState(false);

  const PERIODS = [
    { id:"1h",  label:"1H",  key:"price_change_percentage_1h_in_currency"  },
    { id:"24h", label:"24H", key:"price_change_percentage_24h_in_currency" },
    { id:"7d",  label:"7D",  key:"price_change_percentage_7d_in_currency"  },
    { id:"30d", label:"30D", key:"price_change_percentage_30d_in_currency" },
  ];

  const fetchAll = useCallback(async () => {
    setErr(null);
    setLoading(true);
    try {
      const [coinsRes, globalRes, fgRes] = await Promise.all([
        fetch("https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=100&page=1&sparkline=false&price_change_percentage=1h,24h,7d,30d")
          .then(r => r.ok ? r.json() : null).catch(()=>null),
        fetch("https://api.coingecko.com/api/v3/global").then(r => r.ok ? r.json() : null).catch(()=>null),
        fetch("https://api.alternative.me/fng/?limit=1").then(r => r.ok ? r.json() : null).catch(()=>null),
      ]);
      if (Array.isArray(coinsRes)) { setCoins(coinsRes); setErr(null); }
      else { setErr(isEN ? "Connection error. Retrying..." : "Error de conexión. Reintentando..."); }
      if (globalRes?.data) setGlobal(globalRes.data);
      if (fgRes?.data?.[0]) setFearGreed(fgRes.data[0]);
      setLastUpdate(new Date());
      setCountdown(60);
    } catch(e) {
      setErr(isEN ? "Connection error. Retrying..." : "Error de conexión. Reintentando...");
    } finally {
      setLoading(false);
    }
  }, [isEN]);

  useEffect(() => { fetchAll(); }, [fetchAll]);
  useEffect(() => {
    const iv = setInterval(() => setCountdown(c => { if(c <= 1){ fetchAll(); return 60; } return c - 1; }), 1000);
    return () => clearInterval(iv);
  }, [fetchAll]);

  const periodKey = PERIODS.find(p => p.id === period)?.key || "price_change_percentage_24h_in_currency";

  function getPct(coin) {
    return coin[periodKey] ?? coin.price_change_percentage_24h ?? 0;
  }

  function getHeatColor(pct) {
    if (pct >= 10)  return { bg:"#065f46", text:"#6ee7b7" };
    if (pct >= 5)   return { bg:"#047857", text:"#a7f3d0" };
    if (pct >= 2)   return { bg:"#059669", text:"#d1fae5" };
    if (pct >= 0.5) return { bg:"#10b981", text:"#fff" };
    if (pct >= 0)   return { bg:"#34d399", text:"#064e3b" };
    if (pct >= -0.5)return { bg:"#f87171", text:"#fff" };
    if (pct >= -2)  return { bg:"#ef4444", text:"#fff" };
    if (pct >= -5)  return { bg:"#dc2626", text:"#fecaca" };
    if (pct >= -10) return { bg:"#b91c1c", text:"#fee2e2" };
    return                 { bg:"#7f1d1d", text:"#fca5a5" };
  }

  function fmt$(n) {
    if (!n && n !== 0) return "—";
    if (n >= 1e12) return `$${(n/1e12).toFixed(2)}T`;
    if (n >= 1e9)  return `$${(n/1e9).toFixed(2)}B`;
    if (n >= 1e6)  return `$${(n/1e6).toFixed(2)}M`;
    return `$${n.toLocaleString("en-US", {minimumFractionDigits:2,maximumFractionDigits:2})}`;
  }
  function fmtPrice(n) {
    if (!n && n !== 0) return "—";
    if (n >= 1000) return `$${n.toLocaleString("en-US",{maximumFractionDigits:0})}`;
    if (n >= 1)    return `$${n.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:4})}`;
    return `$${n.toFixed(6)}`;
  }
  function fmtPct(n) { return n == null ? "—" : `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`; }

  const filtered = coins
    .filter(c => !search || c.name.toLowerCase().includes(search.toLowerCase()) || c.symbol.toLowerCase().includes(search.toLowerCase()))
    .sort((a,b) => {
      let va = a[sortCol], vb = b[sortCol];
      if (sortCol === "pct") { va = getPct(a); vb = getPct(b); }
      if (va == null) va = 0; if (vb == null) vb = 0;
      return sortAsc ? va - vb : vb - va;
    });

  const fgVal = fearGreed ? parseInt(fearGreed.value) : null;
  const fgColor = fgVal>75?"#22c55e":fgVal>55?"#a3e635":fgVal>45?"#fbbf24":fgVal>25?"#f97316":"#ef4444";

  // ── RENDER ──────────────────────────────────────────────────────────────────
  return (
    <div style={{background:"#090e1a",minHeight:"100vh",padding:"0 0 40px",fontFamily:"system-ui,-apple-system,sans-serif"}}>

      {/* ── HEADER ── */}
      <div style={{background:"linear-gradient(180deg,#0d1627,#090e1a)",borderBottom:"1px solid rgba(255,255,255,0.06)",padding:"14px 20px"}}>
        <div style={{maxWidth:1600,margin:"0 auto",display:"flex",alignItems:"center",flexWrap:"wrap",gap:12}}>
          <div>
            <div style={{fontSize:18,fontWeight:900,color:"#f1f5f9",letterSpacing:-0.5}}>₿ {isEN?"Crypto Performance":"Performance Crypto"}</div>
            <div style={{fontSize:10,color:"#475569",fontWeight:600,letterSpacing:0.5,textTransform:"uppercase",marginTop:1}}>{isEN?"Real-time · Top 100 by market cap · CoinGecko":"Tiempo real · Top 100 por market cap · CoinGecko"}</div>
          </div>

          {/* Period tabs */}
          <div style={{display:"flex",gap:2,background:"rgba(255,255,255,0.05)",borderRadius:9,padding:3}}>
            {PERIODS.map(p => (
              <button key={p.id} onClick={()=>setPeriod(p.id)}
                style={{background:period===p.id?"#0066FF":"transparent",color:period===p.id?"#fff":"#64748b",border:"none",borderRadius:6,padding:"5px 14px",fontWeight:700,fontSize:12,cursor:"pointer",transition:"all 0.15s"}}>
                {p.label}
              </button>
            ))}
          </div>

          {/* View toggle */}
          <div style={{display:"flex",gap:2,background:"rgba(255,255,255,0.05)",borderRadius:9,padding:3}}>
            {[["heatmap","🔥 Heatmap"],["table","📋 "+ (isEN?"Table":"Tabla")]].map(([id,lbl])=>(
              <button key={id} onClick={()=>setView(id)}
                style={{background:view===id?"rgba(255,255,255,0.12)":"transparent",color:view===id?"#f1f5f9":"#64748b",border:"none",borderRadius:6,padding:"5px 12px",fontWeight:700,fontSize:11,cursor:"pointer"}}>
                {lbl}
              </button>
            ))}
          </div>

          {/* Search */}
          <input value={search} onChange={e=>setSearch(e.target.value)}
            placeholder={isEN?"Search BTC, ETH...":"Buscar BTC, ETH..."}
            style={{background:"rgba(255,255,255,0.07)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:8,color:"#f1f5f9",padding:"6px 12px",fontSize:12,outline:"none",width:160}}/>

          <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:10}}>
            {lastUpdate && <div style={{fontSize:10,color:"#475569",textAlign:"right"}}>
              <div style={{color:"#22c55e",fontWeight:700,fontSize:11}}>● LIVE</div>
              <div>{isEN?"Refreshes in":"Actualiza en"} {countdown}s</div>
            </div>}
            <button onClick={fetchAll} disabled={loading}
              style={{background:"rgba(0,102,255,0.1)",border:"1px solid rgba(0,102,255,0.3)",borderRadius:8,color:"#0066FF",padding:"6px 14px",fontSize:12,fontWeight:700,cursor:"pointer"}}>
              {loading?"⏳":"🔄"} {isEN?"Refresh":"Actualizar"}
            </button>
          </div>
        </div>
      </div>

      {/* ── MARKET STATS BAR ── */}
      {global && (
        <div style={{background:"#0d1627",borderBottom:"1px solid rgba(255,255,255,0.05)",padding:"8px 20px",overflowX:"auto"}}>
          <div style={{maxWidth:1600,margin:"0 auto",display:"flex",gap:0,minWidth:600}}>
            {[
              {label:isEN?"Market Cap":"Cap. Total", val:fmt$(global.total_market_cap?.usd), sub:`${global.market_cap_change_percentage_24h_usd?.toFixed(2)}% 24h`, color:global.market_cap_change_percentage_24h_usd>=0?"#22c55e":"#f87171"},
              {label:isEN?"24h Volume":"Vol. 24h",   val:fmt$(global.total_volume?.usd), sub:`${global.active_cryptocurrencies?.toLocaleString()} activas`, color:"#f1f5f9"},
              {label:"BTC Dom.",                     val:`${global.market_cap_percentage?.btc?.toFixed(1)}%`, sub:`ETH ${global.market_cap_percentage?.eth?.toFixed(1)}%`, color:"#F7931A"},
              {label:isEN?"Cryptos":"Criptos",       val:global.active_cryptocurrencies?.toLocaleString(), sub:isEN?"active markets":"mercados activos", color:"#f1f5f9"},
              {label:"Fear & Greed",                 val:fearGreed?.value||"—", sub:fearGreed?.value_classification||"—", color:fgColor},
            ].map((m,i) => (
              <div key={i} style={{flex:"1 1 100px",padding:"6px 16px",borderRight:i<4?"1px solid rgba(255,255,255,0.05)":"none"}}>
                <div style={{fontSize:9,color:"#64748b",fontWeight:700,letterSpacing:0.5,textTransform:"uppercase",marginBottom:2}}>{m.label}</div>
                <div style={{fontSize:14,fontWeight:800,color:m.color,letterSpacing:-0.3}}>{m.val}</div>
                <div style={{fontSize:10,color:"#475569"}}>{m.sub}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── CONTENT ── */}
      <div style={{maxWidth:1600,margin:"0 auto",padding:"16px 20px"}}>

        {err && <div style={{background:"rgba(239,68,68,0.1)",border:"1px solid rgba(239,68,68,0.3)",borderRadius:10,padding:"10px 16px",color:"#f87171",fontSize:13,marginBottom:12}}>⚠️ {err}</div>}

        {/* ── HEATMAP VIEW ── */}
        {view === "heatmap" && (
          <div>
            {/* Legend */}
            <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:12,flexWrap:"wrap"}}>
              <span style={{fontSize:10,color:"#475569",fontWeight:700,textTransform:"uppercase",letterSpacing:0.5}}>{isEN?"Performance":"Rendimiento"} {PERIODS.find(p=>p.id===period)?.label}:</span>
              {[["#7f1d1d","<-10%"],["#b91c1c","-10% / -5%"],["#dc2626","-5% / -2%"],["#ef4444","-2% / 0%"],["#34d399","0% / +2%"],["#10b981","+2% / +5%"],["#047857","+5% / +10%"],["#065f46",">+10%"]].map(([bg,lbl])=>(
                <div key={lbl} style={{display:"flex",alignItems:"center",gap:4}}>
                  <div style={{width:12,height:12,borderRadius:3,background:bg}}/>
                  <span style={{fontSize:9,color:"#64748b"}}>{lbl}</span>
                </div>
              ))}
            </div>
            {loading ? (
              <div style={{display:"flex",flexWrap:"wrap",gap:4}}>
                {Array(50).fill(0).map((_,i)=>(
                  <div key={i} style={{height:80,width:`${60+Math.random()*60}px`,background:"rgba(255,255,255,0.05)",borderRadius:8,animation:"pulse 1.4s infinite",flex:`0 0 ${60+i%4*20}px`}}/>
                ))}
              </div>
            ) : (
              <div style={{display:"flex",flexWrap:"wrap",gap:3,alignItems:"flex-start",alignContent:"flex-start"}}>
                {filtered.map(coin => {
                  const pct  = getPct(coin);
                  const {bg, text} = getHeatColor(pct);
                  // Size by market cap rank (rank 1 = biggest)
                  const rankFactor = Math.max(0.3, 1 - (coin.market_cap_rank - 1) / 100);
                  const w = Math.round(60 + rankFactor * 100);
                  const h = Math.round(55 + rankFactor * 55);
                  return (
                    <div key={coin.id}
                      style={{width:w,height:h,background:bg,borderRadius:8,padding:"6px 7px",cursor:"pointer",display:"flex",flexDirection:"column",justifyContent:"space-between",transition:"transform 0.12s,filter 0.12s",userSelect:"none",flexShrink:0,overflow:"hidden"}}
                      title={`${coin.name} · ${fmtPrice(coin.current_price)} · ${fmtPct(pct)}`}
                      onMouseEnter={e=>{e.currentTarget.style.transform="scale(1.04)";e.currentTarget.style.filter="brightness(1.15)";e.currentTarget.style.zIndex="5";e.currentTarget.style.position="relative";}}
                      onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.filter="";e.currentTarget.style.zIndex="";e.currentTarget.style.position="";}}>
                      <div>
                        <div style={{fontWeight:800,fontSize:Math.max(9,Math.min(14,w/7)),color:text,lineHeight:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{coin.symbol.toUpperCase()}</div>
                        {w > 75 && <div style={{fontSize:9,color:`${text}bb`,marginTop:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{coin.name}</div>}
                      </div>
                      <div>
                        {h > 75 && <div style={{fontSize:Math.max(8,Math.min(12,w/9)),color:`${text}cc`,marginBottom:1}}>{fmtPrice(coin.current_price)}</div>}
                        <div style={{fontWeight:800,fontSize:Math.max(9,Math.min(14,w/7)),color:text}}>{fmtPct(pct)}</div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ── TABLE VIEW ── */}
        {view === "table" && (
          <div style={{overflowX:"auto"}}>
            <table style={{width:"100%",borderCollapse:"collapse",minWidth:700}}>
              <thead>
                <tr style={{borderBottom:"1px solid rgba(255,255,255,0.07)"}}>
                  {[
                    {label:"#", col:"market_cap_rank", w:40},
                    {label:isEN?"Name":"Nombre", col:"name", w:180},
                    {label:isEN?"Price":"Precio", col:"current_price", w:110},
                    {label:"1H %", col:"price_change_percentage_1h_in_currency", w:80},
                    {label:"24H %", col:"pct", w:80},
                    {label:"7D %", col:"price_change_percentage_7d_in_currency", w:80},
                    {label:isEN?"Market Cap":"Cap. Mercado", col:"market_cap", w:130},
                    {label:isEN?"Volume 24H":"Vol. 24H", col:"total_volume", w:120},
                  ].map(h=>(
                    <th key={h.col} onClick={()=>{ if(sortCol===h.col) setSortAsc(!sortAsc); else{setSortCol(h.col);setSortAsc(false);} }}
                      style={{textAlign:"left",padding:"8px 10px",fontSize:10,fontWeight:700,color:sortCol===h.col?"#0066FF":"#64748b",letterSpacing:0.5,textTransform:"uppercase",cursor:"pointer",whiteSpace:"nowrap",width:h.w}}>
                      {h.label}{sortCol===h.col?(sortAsc?" ↑":" ↓"):""}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {loading && Array(15).fill(0).map((_,i)=>(
                  <tr key={i}><td colSpan={8} style={{padding:"10px"}}>
                    <div style={{height:14,background:"rgba(255,255,255,0.05)",borderRadius:4,animation:"pulse 1.4s infinite"}}/>
                  </td></tr>
                ))}
                {!loading && filtered.map((coin,i)=>{
                  const pct24  = coin.price_change_percentage_24h_in_currency ?? coin.price_change_percentage_24h ?? 0;
                  const pct1h  = coin.price_change_percentage_1h_in_currency ?? 0;
                  const pct7d  = coin.price_change_percentage_7d_in_currency ?? 0;
                  const rowBg  = i%2===0?"rgba(255,255,255,0.02)":"transparent";
                  return (
                    <tr key={coin.id} style={{background:rowBg,transition:"background 0.1s"}}
                      onMouseEnter={e=>e.currentTarget.style.background="rgba(0,102,255,0.05)"}
                      onMouseLeave={e=>e.currentTarget.style.background=rowBg}>
                      <td style={{padding:"9px 10px",color:"#475569",fontSize:11,fontFamily:"monospace"}}>{coin.market_cap_rank}</td>
                      <td style={{padding:"9px 10px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:8}}>
                          <img src={coin.image} alt={coin.symbol} width={22} height={22} style={{borderRadius:"50%",flexShrink:0}} onError={e=>e.target.style.display="none"}/>
                          <div>
                            <div style={{fontWeight:700,color:"#f1f5f9",fontSize:13}}>{coin.symbol.toUpperCase()}</div>
                            <div style={{fontSize:10,color:"#475569"}}>{coin.name}</div>
                          </div>
                        </div>
                      </td>
                      <td style={{padding:"9px 10px",fontWeight:700,color:"#f1f5f9",fontSize:13,fontFamily:"monospace"}}>{fmtPrice(coin.current_price)}</td>
                      <td style={{padding:"9px 10px",fontWeight:700,fontSize:12,color:pct1h>=0?"#22c55e":"#f87171",fontFamily:"monospace"}}>{fmtPct(pct1h)}</td>
                      <td style={{padding:"9px 10px",fontWeight:700,fontSize:12,color:pct24>=0?"#22c55e":"#f87171",fontFamily:"monospace"}}>{fmtPct(pct24)}</td>
                      <td style={{padding:"9px 10px",fontWeight:700,fontSize:12,color:pct7d>=0?"#22c55e":"#f87171",fontFamily:"monospace"}}>{fmtPct(pct7d)}</td>
                      <td style={{padding:"9px 10px",color:"#94a3b8",fontSize:12,fontFamily:"monospace"}}>{fmt$(coin.market_cap)}</td>
                      <td style={{padding:"9px 10px",color:"#94a3b8",fontSize:12,fontFamily:"monospace"}}>{fmt$(coin.total_volume)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* Top Gainers / Losers */}
        {!loading && view === "heatmap" && (
          <div className="nexo-crypto-toplist" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginTop:20}}>
            {[
              {title:isEN?"🚀 Top Gainers":"🚀 Mayores Subidas",dir:1},
              {title:isEN?"💀 Top Losers":"💀 Mayores Caídas",dir:-1},
            ].map(({title,dir})=>{
              const list = [...coins].sort((a,b)=>dir*(getPct(b)-getPct(a))).slice(0,5);
              return (
                <div key={dir} style={{background:"#0d1627",border:"1px solid rgba(255,255,255,0.06)",borderRadius:12,padding:"14px 16px"}}>
                  <div style={{fontWeight:800,fontSize:13,color:"#f1f5f9",marginBottom:10}}>{title} ({PERIODS.find(p=>p.id===period)?.label})</div>
                  {list.map(c=>{
                    const pct=getPct(c);
                    const {bg,text}=getHeatColor(pct);
                    return (
                      <div key={c.id} style={{display:"flex",alignItems:"center",gap:10,marginBottom:8,padding:"6px 8px",borderRadius:8,background:"rgba(255,255,255,0.03)"}}>
                        <img src={c.image} alt={c.symbol} width={24} height={24} style={{borderRadius:"50%"}} onError={e=>e.target.style.display="none"}/>
                        <div style={{flex:1}}>
                          <div style={{fontWeight:700,color:"#f1f5f9",fontSize:12}}>{c.symbol.toUpperCase()} <span style={{color:"#475569",fontWeight:400,fontSize:10}}>{c.name}</span></div>
                          <div style={{color:"#64748b",fontSize:11,fontFamily:"monospace"}}>{fmtPrice(c.current_price)}</div>
                        </div>
                        <div style={{background:bg,color:text,borderRadius:6,padding:"3px 9px",fontWeight:800,fontSize:12,fontFamily:"monospace"}}>{fmtPct(pct)}</div>
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        )}

        <div style={{marginTop:14,fontSize:10,color:"#334155",textAlign:"center"}}>
          📡 {isEN?"Data: CoinGecko API · Updates every 60s · Not financial advice":"Datos: CoinGecko API · Actualiza cada 60s · No es consejo financiero"}
        </div>
      </div>
    </div>
  );
}

// ── CRYPTO OPTIONS PAGE (page 41) ─────────────────────────────────────────────
function CryptoOptionsPage({ isPremium, onNeedPremium, lang="es" }) {
  const isEN = lang==="en";
  const MONTHS = {JAN:0,FEB:1,MAR:2,APR:3,MAY:4,JUN:5,JUL:6,AUG:7,SEP:8,OCT:9,NOV:10,DEC:11};
  const COLOR_MAP = {
    BTC:{color:"#F7931A",emoji:"₿"}, ETH:{color:"#627EEA",emoji:"Ξ"},
    SOL:{color:"#9945FF",emoji:"◎"}, MATIC:{color:"#8247E5",emoji:"⬡"},
    XRP:{color:"#00AAE4",emoji:"✕"}, LINK:{color:"#2A5ADA",emoji:"⬡"},
    DOGE:{color:"#C3A634",emoji:"Ð"}, ADA:{color:"#0033AD",emoji:"₳"},
    AVAX:{color:"#E84142",emoji:"▲"}, DOT:{color:"#E6007A",emoji:"●"},
    BNB:{color:"#F3BA2F",emoji:"◈"}, ATOM:{color:"#6F4E37",emoji:"⚛"},
    NEAR:{color:"#00C08B",emoji:"Ⓝ"}, UNI:{color:"#FF007A",emoji:"🦄"},
    LTC:{color:"#BFBBBB",emoji:"Ł"}, BCH:{color:"#8DC351",emoji:"₿"},
  };
  const DEFAULT_ASSETS = [
    {sym:"BTC",idx:"btc_usd",color:"#F7931A",emoji:"₿"},
    {sym:"ETH",idx:"eth_usd",color:"#627EEA",emoji:"Ξ"},
    {sym:"SOL",idx:"sol_usd",color:"#9945FF",emoji:"◎"},
  ];

  const [assets, setAssets]             = useState(DEFAULT_ASSETS);
  const [assetIdx, setAssetIdx]         = useState(0);
  const [expiries, setExpiries]         = useState([]);
  const [selExpiry, setSelExpiry]       = useState(null);
  const [allOpts, setAllOpts]           = useState([]);
  const [spot, setSpot]                 = useState(null);
  const [loading, setLoading]           = useState(true);
  const [err, setErr]                   = useState(null);
  const [lastUpdate, setLastUpdate]     = useState(null);
  const [countdown, setCountdown]       = useState(30);
  const [tab, setTab]                   = useState("chain");
  const [fearGreed, setFearGreed]       = useState(null);
  const [showAlertModal, setShowAlertModal] = useState(false);
  const [alertPrice, setAlertPrice]     = useState("");
  const [alertDir, setAlertDir]         = useState("above");
  const [myAlerts, setMyAlerts]         = useState([]);
  const [firedAlerts, setFiredAlerts]   = useState([]);
  const [filterATM, setFilterATM]       = useState(true);
  const [sortCol, setSortCol]           = useState("oi");

  const asset = assets[assetIdx] || assets[0];

  // Cargar monedas disponibles dinámicamente desde Deribit
  useEffect(()=>{
    fetch("https://www.deribit.com/api/v2/public/get_currencies")
      .then(r=>r.json())
      .then(data=>{
        const STABLE = ["USDC","USDT","EURR","STETH","CBETH"];
        const list = (data.result||[])
          .filter(c=>!STABLE.includes(c.currency))
          .map(c=>({
            sym:c.currency,
            idx:`${c.currency.toLowerCase()}_usd`,
            ...(COLOR_MAP[c.currency]||{color:"#64748b",emoji:"●"}),
          }));
        if(list.length>0) setAssets(list);
      })
      .catch(()=>{}); // mantiene defaults si falla
  },[]);

  function parseExpiry(str) {
    try {
      const day=parseInt(str.slice(0,2)),mon=MONTHS[str.slice(2,5)],yr=2000+parseInt(str.slice(5));
      return new Date(yr,mon,day);
    } catch { return new Date(); }
  }
  function daysToExpiry(str) {
    return Math.max(0,Math.ceil((parseExpiry(str)-new Date())/86400000));
  }
  function fmtExp(str) {
    const d=parseExpiry(str);
    return d.toLocaleDateString(isEN?"en-US":"es-ES",{day:"numeric",month:"short",year:"2-digit"});
  }

  const fetchData = useCallback(async () => {
    setLoading(true); setErr(null);
    try {
      const base="https://www.deribit.com/api/v2/public";
      const [sRes,oRes] = await Promise.all([
        fetch(`${base}/get_index_price?index_name=${asset.idx}`).then(r=>r.json()),
        fetch(`${base}/get_book_summary_by_currency?currency=${asset.sym}&kind=option`).then(r=>r.json()),
      ]);
      const sp = sRes.result?.index_price || 0;
      setSpot(sp);
      const opts = (oRes.result||[]).map(o=>{
        const p=o.instrument_name.split("-");
        return {
          name:o.instrument_name, strike:parseFloat(p[2]), type:p[3], expiry:p[1],
          markUSD:(o.mark_price||0)*sp, bidUSD:(o.bid_price||0)*sp, askUSD:(o.ask_price||0)*sp,
          oi:o.open_interest||0, vol24h:o.volume||0, iv:Math.round(o.mark_iv||0),
          delta:o.greeks?.delta||0, gamma:o.greeks?.gamma||0,
          vega:o.greeks?.vega||0, theta:o.greeks?.theta||0,
        };
      });
      setAllOpts(opts);
      const exps=[...new Set(opts.map(o=>o.expiry))].sort((a,b)=>parseExpiry(a)-parseExpiry(b));
      setExpiries(exps);
      setSelExpiry(prev => (prev && exps.includes(prev)) ? prev : (exps[0]||null));
      setLastUpdate(new Date()); setCountdown(30);
    } catch(e) { setErr(isEN?"Connection error with Deribit. Retrying...":"Error al conectar con Deribit. Reintentando..."); }
    finally { setLoading(false); }
  }, [asset.sym, asset.idx]);

  useEffect(()=>{ fetchData(); },[fetchData]);
  useEffect(()=>{
    const iv=setInterval(()=>setCountdown(c=>{ if(c<=1){fetchData();return 30;} return c-1; }),1000);
    return ()=>clearInterval(iv);
  },[fetchData]);
  useEffect(()=>{
    fetch("https://api.alternative.me/fng/?limit=1").then(r=>r.json()).then(d=>setFearGreed(d.data?.[0])).catch(()=>{});
  },[]);
  useEffect(()=>{
    if(!spot||!myAlerts.length) return;
    const fired=myAlerts.filter(a=>(a.dir==="above"&&spot>=a.price)||(a.dir==="below"&&spot<=a.price));
    if(fired.length){ setFiredAlerts(f=>[...f,...fired.map(a=>({...a,firedAt:spot}))]);
      setMyAlerts(p=>p.filter(a=>!fired.includes(a))); }
  },[spot,myAlerts]);

  const expiryOpts = allOpts.filter(o=>o.expiry===selExpiry);
  const strikes    = [...new Set(expiryOpts.map(o=>o.strike))].sort((a,b)=>a-b);
  const visStrikes = filterATM && spot
    ? strikes.filter(s=>Math.abs(s-spot)/spot<0.30)
    : strikes;

  const callOI    = expiryOpts.filter(o=>o.type==="C").reduce((s,o)=>s+o.oi,0);
  const putOI     = expiryOpts.filter(o=>o.type==="P").reduce((s,o)=>s+o.oi,0);
  const totalOI   = callOI+putOI;
  const pcRatio   = callOI>0?(putOI/callOI).toFixed(2):"—";
  const vol24h    = expiryOpts.reduce((s,o)=>s+o.vol24h,0);
  const allCallOI = allOpts.filter(o=>o.type==="C").reduce((s,o)=>s+o.oi,0);
  const allPutOI  = allOpts.filter(o=>o.type==="P").reduce((s,o)=>s+o.oi,0);

  const maxPain = useMemo(()=>{
    if(!spot||!strikes.length) return null;
    let best=Infinity,mp=null;
    for(const ts of strikes){
      let pain=0;
      for(const s of strikes){
        const c=expiryOpts.find(o=>o.strike===s&&o.type==="C");
        const p=expiryOpts.find(o=>o.strike===s&&o.type==="P");
        if(c&&ts>s) pain+=(ts-s)*c.oi;
        if(p&&ts<s) pain+=(s-ts)*p.oi;
      }
      if(pain<best){best=pain;mp=ts;}
    }
    return mp;
  },[strikes,expiryOpts,spot]);

  const fgVal   = fearGreed ? parseInt(fearGreed.value) : null;
  const fgColor = fgVal>75?"#22c55e":fgVal>55?"#a3e635":fgVal>45?"#fbbf24":fgVal>25?"#f97316":"#ef4444";
  const fgLabel = fearGreed?.value_classification || "—";

  const fmtP = n => !n?"—":`$${n.toLocaleString("en-US",{minimumFractionDigits:0,maximumFractionDigits:0})}`;
  const fmtN = n => !n?"—":`${n.toFixed(2)}`;
  const fmtOI= n => n>=1000?`${(n/1000).toFixed(1)}K`:`${n}`;
  const fmtVol= n => n>=1e6?`${(n/1e6).toFixed(2)}M`:n>=1000?`${(n/1000).toFixed(1)}K`:`${n.toFixed(0)}`;

  const thSt={fontSize:10,fontWeight:700,color:"rgba(148,163,184,0.8)",letterSpacing:"0.08em",textTransform:"uppercase",padding:"7px 6px",textAlign:"right",borderBottom:"1px solid rgba(255,255,255,0.07)",whiteSpace:"nowrap"};
  const tdSt={fontSize:11,padding:"5px 6px",textAlign:"right",borderBottom:"1px solid rgba(255,255,255,0.04)",fontVariantNumeric:"tabular-nums",fontFamily:"'SF Mono',monospace,system-ui"};

  // ── RENDER ──────────────────────────────────────────────────────────────────
  return (
    <div style={{background:"#090e1a",minHeight:"100vh",padding:"0 0 40px",fontFamily:"system-ui,-apple-system,sans-serif"}}>

      {/* ─ FIRED ALERTS ─ */}
      {firedAlerts.map((a,i)=>(
        <div key={i} onClick={()=>setFiredAlerts(f=>f.filter((_,j)=>j!==i))}
          style={{position:"fixed",top:16+i*68,right:20,zIndex:9999,background:"linear-gradient(135deg,#1e293b,#0f172a)",border:"1px solid #f59e0b",borderRadius:12,padding:"12px 18px",cursor:"pointer",boxShadow:"0 8px 32px rgba(0,0,0,0.6)",minWidth:220}}>
          <div style={{color:"#f59e0b",fontWeight:800,fontSize:13}}>🔔 {isEN?"Alert triggered!":"¡Alerta activada!"}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:3}}>{asset.sym} {a.dir==="above"?(isEN?"went above":"superó"):(isEN?"fell below":"cayó bajo")} {fmtP(a.price)} → {fmtP(a.firedAt)}</div>
        </div>
      ))}

      {/* ─ ALERT MODAL ─ */}
      {showAlertModal && (
        <div style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,0.7)",display:"flex",alignItems:"center",justifyContent:"center"}} onClick={()=>setShowAlertModal(false)}>
          <div style={{background:"#0f172a",border:"1px solid rgba(0,102,255,0.3)",borderRadius:18,padding:28,width:320,boxShadow:"0 24px 64px rgba(0,0,0,0.8)"}} onClick={e=>e.stopPropagation()}>
            <div style={{fontWeight:800,fontSize:16,color:"#f1f5f9",marginBottom:18}}>🔔 {isEN?"Set Price Alert":"Crear Alerta de Precio"}</div>
            <div style={{fontSize:12,color:"#94a3b8",marginBottom:6}}>{isEN?"Asset":"Activo"}: <span style={{color:asset.color,fontWeight:700}}>{asset.emoji} {asset.sym}</span> · {isEN?"Current":"Actual"}: <span style={{color:"#0066FF",fontWeight:700}}>{fmtP(spot)}</span></div>
            <select value={alertDir} onChange={e=>setAlertDir(e.target.value)}
              style={{width:"100%",background:"#1e293b",border:"1px solid rgba(255,255,255,0.1)",borderRadius:8,color:"#f1f5f9",padding:"9px 12px",fontSize:13,marginBottom:10,outline:"none"}}>
              <option value="above">{isEN?"Price goes ABOVE":"Precio sube SOBRE"}</option>
              <option value="below">{isEN?"Price falls BELOW":"Precio cae BAJO"}</option>
            </select>
            <input type="number" value={alertPrice} onChange={e=>setAlertPrice(e.target.value)}
              placeholder={`${isEN?"Strike price e.g.":"Precio ej."} ${spot?Math.round(spot/1000)*1000:100000}`}
              style={{width:"100%",boxSizing:"border-box",background:"#1e293b",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,color:"#f1f5f9",padding:"9px 12px",fontSize:14,marginBottom:14,outline:"none"}}/>
            {myAlerts.length>0 && (
              <div style={{marginBottom:12}}>
                <div style={{fontSize:11,color:"#64748b",fontWeight:700,marginBottom:6,textTransform:"uppercase",letterSpacing:0.5}}>{isEN?"Active alerts":"Alertas activas"}</div>
                {myAlerts.map((a,i)=>(
                  <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",background:"#1e293b",borderRadius:7,padding:"6px 10px",marginBottom:4}}>
                    <span style={{fontSize:11,color:"#94a3b8"}}>{a.dir==="above"?"▲":"▼"} {fmtP(a.price)}</span>
                    <button onClick={()=>setMyAlerts(p=>p.filter((_,j)=>j!==i))} style={{background:"none",border:"none",color:"#ef4444",cursor:"pointer",fontSize:14,lineHeight:1}}>×</button>
                  </div>
                ))}
              </div>
            )}
            <button onClick={()=>{
              if(!alertPrice) return;
              setMyAlerts(p=>[...p,{dir:alertDir,price:parseFloat(alertPrice),asset:asset.sym}]);
              setAlertPrice(""); setShowAlertModal(false);
            }} style={{width:"100%",background:"linear-gradient(135deg,#0066FF,#0070aa)",border:"none",borderRadius:10,color:"#fff",padding:"11px",fontWeight:700,fontSize:14,cursor:"pointer"}}>
              {isEN?"Set Alert":"Crear Alerta"}
            </button>
          </div>
        </div>
      )}

      {/* ─ HEADER ─ */}
      <div style={{background:"linear-gradient(180deg,#0d1627 0%,#090e1a 100%)",borderBottom:"1px solid rgba(255,255,255,0.06)",padding:"14px 24px"}}>
        <div style={{maxWidth:1600,margin:"0 auto",display:"flex",alignItems:"center",flexWrap:"wrap",gap:12}}>
          {/* Title */}
          <div style={{marginRight:8}}>
            <div style={{fontSize:18,fontWeight:900,color:"#f1f5f9",letterSpacing:-0.5,lineHeight:1}}>
              📊 {isEN?"Crypto Options":"Opciones Crypto"}
            </div>
            <div style={{fontSize:10,color:"#64748b",fontWeight:600,letterSpacing:0.5,textTransform:"uppercase",marginTop:2}}>
              {isEN?"Real-time · 24h · Powered by Deribit":"Tiempo real · 24h · Powered by Deribit"}
            </div>
          </div>

          {/* Asset tabs — scrollable, dinámico */}
          <div style={{display:"flex",gap:3,background:"rgba(255,255,255,0.04)",borderRadius:10,padding:3,overflowX:"auto",maxWidth:"100%",flexShrink:1,scrollbarWidth:"none"}}>
            {assets.map((a,i)=>(
              <button key={a.sym} onClick={()=>{setAssetIdx(i);setSelExpiry(null);}}
                style={{background:assetIdx===i?a.color:"transparent",color:assetIdx===i?"#000":a.color,
                  border:assetIdx===i?"none":`1px solid ${a.color}33`,
                  borderRadius:7,padding:"5px 11px",fontWeight:800,fontSize:12,cursor:"pointer",
                  transition:"all 0.15s",whiteSpace:"nowrap",flexShrink:0}}>
                {a.emoji} {a.sym}
              </button>
            ))}
          </div>

          {/* Expiry selector */}
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:11,color:"#64748b",fontWeight:700,textTransform:"uppercase",letterSpacing:0.5}}>{isEN?"Expiry":"Vence"}</span>
            <select value={selExpiry||""} onChange={e=>setSelExpiry(e.target.value)}
              style={{background:"#1e293b",border:"1px solid rgba(255,255,255,0.1)",borderRadius:8,color:"#f1f5f9",padding:"6px 10px",fontSize:12,fontWeight:700,cursor:"pointer",outline:"none"}}>
              {expiries.map(e=>(
                <option key={e} value={e}>{fmtExp(e)} ({daysToExpiry(e)}d)</option>
              ))}
            </select>
          </div>

          <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:10}}>
            {/* Last update */}
            {lastUpdate && (
              <div style={{fontSize:10,color:"#475569",textAlign:"right"}}>
                <div style={{color:"#22c55e",fontWeight:700,fontSize:11}}>● LIVE</div>
                <div>{isEN?"Next update in":"Actualiza en"} {countdown}s</div>
              </div>
            )}
            {/* Refresh */}
            <button onClick={fetchData} disabled={loading}
              style={{background:"rgba(0,102,255,0.1)",border:"1px solid rgba(0,102,255,0.3)",borderRadius:9,color:"#0066FF",padding:"7px 14px",fontSize:12,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
              {loading?"⏳":"🔄"} {isEN?"Refresh":"Actualizar"}
            </button>
            {/* Alert */}
            <button onClick={()=>setShowAlertModal(true)}
              style={{background:myAlerts.length?"rgba(245,158,11,0.15)":"rgba(255,255,255,0.05)",border:`1px solid ${myAlerts.length?"#f59e0b":"rgba(255,255,255,0.1)"}`,borderRadius:9,color:myAlerts.length?"#f59e0b":"#64748b",padding:"7px 14px",fontSize:12,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
              🔔 {isEN?"Alerts":"Alertas"}{myAlerts.length?` (${myAlerts.length})`:""}
            </button>
          </div>
        </div>
      </div>

      {/* ─ METRICS STRIP ─ */}
      <div style={{background:"#0d1627",borderBottom:"1px solid rgba(255,255,255,0.05)",padding:"10px 24px"}}>
        <div style={{maxWidth:1600,margin:"0 auto",display:"flex",gap:0,flexWrap:"wrap"}}>
          {[
            {label:asset.sym, val:fmtP(spot), sub:loading?"…":"SPOT", color:asset.color, bold:true},
            {label:isEN?"Total OI":"OI Total", val:fmtOI(allCallOI+allPutOI), sub:`${asset.sym} (${isEN?"all expiries":"todos los venc."})`, color:"#f1f5f9"},
            {label:"Put/Call", val:callOI>0?(allPutOI/allCallOI).toFixed(2):"—", sub:parseFloat(callOI>0?(allPutOI/allCallOI).toFixed(2):0)<0.7?isEN?"🟢 Bullish":"🟢 Alcista":parseFloat(callOI>0?(allPutOI/allCallOI).toFixed(2):0)>1.2?isEN?"🔴 Bearish":"🔴 Bajista":isEN?"🟡 Neutral":"🟡 Neutral", color:parseFloat(callOI>0?(allPutOI/allCallOI).toFixed(2):0)<0.7?"#22c55e":parseFloat(callOI>0?(allPutOI/allCallOI).toFixed(2):0)>1.2?"#f87171":"#fbbf24"},
            {label:"Max Pain", val:maxPain?fmtP(maxPain):"—", sub:maxPain&&spot?`${((maxPain-spot)/spot*100).toFixed(1)}% vs spot`:"", color:"#a78bfa"},
            {label:isEN?"24h Volume":"Vol. 24h", val:fmtOI(vol24h), sub:`${asset.sym} ${isEN?"selected expiry":"venc. sel."}`, color:"#f1f5f9"},
            {label:"Fear & Greed", val:fearGreed?fearGreed.value:"—", sub:fgLabel.length>18?fgLabel.slice(0,18)+"…":fgLabel, color:fgColor},
          ].map((m,i)=>(
            <div key={i} style={{flex:"1 1 120px",padding:"8px 16px",borderRight:i<5?"1px solid rgba(255,255,255,0.06)":"none"}}>
              <div style={{fontSize:9,color:"#64748b",fontWeight:700,letterSpacing:0.6,textTransform:"uppercase",marginBottom:3}}>{m.label}</div>
              <div style={{fontSize:m.bold?20:16,fontWeight:800,color:m.color,letterSpacing:-0.5,lineHeight:1.1}}>{m.val}</div>
              <div style={{fontSize:10,color:"#475569",marginTop:2}}>{m.sub}</div>
            </div>
          ))}
        </div>
      </div>

      {/* ─ OI BAR (calls vs puts visual) ─ */}
      <div style={{background:"#0d1627",borderBottom:"1px solid rgba(255,255,255,0.05)",padding:"8px 24px"}}>
        <div style={{maxWidth:1600,margin:"0 auto",display:"flex",alignItems:"center",gap:12}}>
          <span style={{fontSize:10,color:"#22c55e",fontWeight:700,whiteSpace:"nowrap"}}>CALLS {fmtOI(allCallOI)}</span>
          <div style={{flex:1,height:6,background:"rgba(255,255,255,0.05)",borderRadius:10,overflow:"hidden",display:"flex"}}>
            <div style={{width:`${allCallOI/(allCallOI+allPutOI)*100}%`,background:"linear-gradient(90deg,#22c55e,#16a34a)",borderRadius:"10px 0 0 10px",transition:"width 0.6s"}}/>
            <div style={{flex:1,background:"linear-gradient(90deg,#dc2626,#f87171)",borderRadius:"0 10px 10px 0"}}/>
          </div>
          <span style={{fontSize:10,color:"#f87171",fontWeight:700,whiteSpace:"nowrap"}}>PUTS {fmtOI(allPutOI)}</span>
        </div>
      </div>

      {/* ─ TABS ─ */}
      <div style={{background:"#0d1627",borderBottom:"1px solid rgba(255,255,255,0.06)",padding:"0 24px"}}>
        <div style={{maxWidth:1600,margin:"0 auto",display:"flex",gap:0}}>
          {[
            {id:"chain",  label:isEN?"📊 Options Chain":"📊 Cadena"},
            {id:"oi",     label:isEN?"📈 Open Interest":"📈 Open Interest"},
            {id:"maxpain",label:"🎯 Max Pain"},
            {id:"expiries",label:isEN?"📅 Expirations":"📅 Vencimientos"},
          ].map(t=>(
            <button key={t.id} onClick={()=>setTab(t.id)}
              style={{background:"none",border:"none",borderBottom:`2px solid ${tab===t.id?"#0066FF":"transparent"}`,color:tab===t.id?"#0066FF":"#64748b",padding:"12px 18px",fontSize:12,fontWeight:tab===t.id?700:500,cursor:"pointer",transition:"all 0.15s",whiteSpace:"nowrap"}}>
              {t.label}
            </button>
          ))}
          <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:8,padding:"8px 0"}}>
            <label style={{fontSize:11,color:"#64748b",fontWeight:600,display:"flex",alignItems:"center",gap:6,cursor:"pointer"}}>
              <input type="checkbox" checked={filterATM} onChange={e=>setFilterATM(e.target.checked)}
                style={{accentColor:"#0066FF"}}/>
              {isEN?"ATM ±30%":"ATM ±30%"}
            </label>
          </div>
        </div>
      </div>

      {/* ─ CONTENT ─ */}
      <div style={{maxWidth:1600,margin:"0 auto",padding:"16px 24px"}}>

        {err && (
          <div style={{background:"rgba(239,68,68,0.1)",border:"1px solid rgba(239,68,68,0.3)",borderRadius:10,padding:"12px 16px",color:"#f87171",fontSize:13,marginBottom:16,display:"flex",alignItems:"center",gap:10}}>
            ⚠️ {err}
            <button onClick={fetchData} style={{marginLeft:"auto",background:"none",border:"1px solid #f87171",borderRadius:7,color:"#f87171",padding:"4px 10px",cursor:"pointer",fontSize:11}}>
              {isEN?"Retry":"Reintentar"}
            </button>
          </div>
        )}

        {/* ── OPTIONS CHAIN TAB ── */}
        {tab==="chain" && (
          <div>
            {/* Column headers legend */}
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
              <div style={{fontSize:11,fontWeight:700,color:"#22c55e",letterSpacing:1,textTransform:"uppercase"}}>◀ CALLS</div>
              <div style={{fontSize:11,fontWeight:700,color:"#f87171",letterSpacing:1,textTransform:"uppercase"}}>PUTS ▶</div>
            </div>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",tableLayout:"fixed"}}>
                <colgroup>
                  <col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/>
                  <col style={{width:"10%"}}/>
                  <col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/><col style={{width:"6%"}}/>
                </colgroup>
                <thead>
                  <tr style={{background:"rgba(34,197,94,0.05)"}}>
                    <th style={{...thSt,color:"#22c55e"}}>Delta</th>
                    <th style={{...thSt,color:"#22c55e"}}>OI</th>
                    <th style={{...thSt,color:"#22c55e"}}>Vol</th>
                    <th style={{...thSt,color:"#22c55e"}}>IV%</th>
                    <th style={{...thSt,color:"#22c55e"}}>Bid</th>
                    <th style={{...thSt,color:"#22c55e"}}>Ask</th>
                    <th style={{...thSt,textAlign:"center",color:"#94a3b8",background:"rgba(148,163,184,0.06)"}}>STRIKE</th>
                    <th style={{...thSt,color:"#f87171"}}>Bid</th>
                    <th style={{...thSt,color:"#f87171"}}>Ask</th>
                    <th style={{...thSt,color:"#f87171"}}>IV%</th>
                    <th style={{...thSt,color:"#f87171"}}>Vol</th>
                    <th style={{...thSt,color:"#f87171"}}>OI</th>
                    <th style={{...thSt,color:"#f87171"}}>Delta</th>
                  </tr>
                </thead>
                <tbody>
                  {loading && [1,2,3,4,5,6,7,8].map(i=>(
                    <tr key={i}>
                      {Array(13).fill(0).map((_,j)=>(
                        <td key={j} style={tdSt}>
                          <div style={{height:10,background:"rgba(255,255,255,0.06)",borderRadius:4,width:j===6?"60%":"80%",margin:"0 auto",animation:"pulse 1.4s infinite"}}/>
                        </td>
                      ))}
                    </tr>
                  ))}
                  {!loading && visStrikes.map(strike=>{
                    const call=expiryOpts.find(o=>o.strike===strike&&o.type==="C");
                    const put =expiryOpts.find(o=>o.strike===strike&&o.type==="P");
                    const isATM=spot&&Math.abs(strike-spot)/spot<0.01;
                    const isITMCall=spot&&strike<spot;
                    const isITMPut =spot&&strike>spot;
                    const rowBg=isATM?"rgba(0,102,255,0.12)":isITMCall?"rgba(34,197,94,0.04)":isITMPut?"rgba(248,113,113,0.04)":"transparent";
                    return (
                      <tr key={strike} style={{background:rowBg,transition:"background 0.15s"}}
                        onMouseEnter={e=>e.currentTarget.style.background=isATM?"rgba(0,102,255,0.18)":"rgba(255,255,255,0.04)"}
                        onMouseLeave={e=>e.currentTarget.style.background=rowBg}>
                        <td style={{...tdSt,color:"#22c55e"}}>{call?fmtN(call.delta):"—"}</td>
                        <td style={{...tdSt,color:"#22c55e"}}>{call?fmtOI(call.oi):"—"}</td>
                        <td style={{...tdSt,color:"#22c55e"}}>{call?fmtVol(call.vol24h):"—"}</td>
                        <td style={{...tdSt,color:"#22c55e"}}>{call?`${call.iv}%`:"—"}</td>
                        <td style={{...tdSt,color:"rgba(34,197,94,0.7)"}}>{call&&call.bidUSD>0?`$${call.bidUSD.toFixed(0)}`:"—"}</td>
                        <td style={{...tdSt,color:"rgba(34,197,94,0.9)"}}>{call&&call.askUSD>0?`$${call.askUSD.toFixed(0)}`:"—"}</td>
                        <td style={{...tdSt,textAlign:"center",fontWeight:isATM?800:600,fontSize:isATM?13:11,
                          color:isATM?"#0066FF":isITMCall?"rgba(34,197,94,0.9)":isITMPut?"rgba(248,113,113,0.9)":"#94a3b8",
                          background:"rgba(148,163,184,0.04)",borderLeft:"1px solid rgba(255,255,255,0.06)",borderRight:"1px solid rgba(255,255,255,0.06)"}}>
                          {isATM && <span style={{display:"block",fontSize:8,color:"#0066FF",letterSpacing:0.5,marginBottom:1}}>◆ ATM</span>}
                          {maxPain===strike && <span style={{display:"block",fontSize:8,color:"#a78bfa",letterSpacing:0.5,marginBottom:1}}>★ MAX PAIN</span>}
                          {fmtP(strike)}
                        </td>
                        <td style={{...tdSt,color:"rgba(248,113,113,0.9)"}}>{put&&put.bidUSD>0?`$${put.bidUSD.toFixed(0)}`:"—"}</td>
                        <td style={{...tdSt,color:"rgba(248,113,113,0.9)"}}>{put&&put.askUSD>0?`$${put.askUSD.toFixed(0)}`:"—"}</td>
                        <td style={{...tdSt,color:"#f87171"}}>{put?`${put.iv}%`:"—"}</td>
                        <td style={{...tdSt,color:"#f87171"}}>{put?fmtVol(put.vol24h):"—"}</td>
                        <td style={{...tdSt,color:"#f87171"}}>{put?fmtOI(put.oi):"—"}</td>
                        <td style={{...tdSt,color:"#f87171"}}>{put?fmtN(put.delta):"—"}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            {!loading && visStrikes.length===0 && (
              <div style={{textAlign:"center",padding:"40px",color:"#475569",fontSize:14}}>
                {isEN?"No data for this expiry":"Sin datos para este vencimiento"}
              </div>
            )}
            {/* Greeks legend */}
            <div style={{marginTop:14,display:"flex",flexWrap:"wrap",gap:16,padding:"10px 0",borderTop:"1px solid rgba(255,255,255,0.06)"}}>
              {[["OI","Open Interest — contratos abiertos"],["IV%","Volatilidad implícita"],["Delta","Sensibilidad al precio del spot"],["Bid/Ask","Precio de compra / venta"]].map(([k,v])=>(
                <span key={k} style={{fontSize:10,color:"#475569"}}><span style={{color:"#64748b",fontWeight:700}}>{k}</span>: {v}</span>
              ))}
            </div>
          </div>
        )}

        {/* ── OPEN INTEREST TAB ── */}
        {tab==="oi" && (
          <div>
            <div style={{marginBottom:16,display:"flex",alignItems:"center",gap:20}}>
              <div style={{fontSize:13,color:"#94a3b8"}}>{isEN?"Open Interest by strike price for expiry":"Open Interest por strike — vencimiento"} <span style={{color:"#0066FF",fontWeight:700}}>{selExpiry?fmtExp(selExpiry):""}</span></div>
              <div style={{display:"flex",gap:16,marginLeft:"auto"}}>
                <span style={{fontSize:11,fontWeight:700,color:"#22c55e"}}>■ Calls {fmtOI(callOI)} {asset.sym}</span>
                <span style={{fontSize:11,fontWeight:700,color:"#f87171"}}>■ Puts {fmtOI(putOI)} {asset.sym}</span>
              </div>
            </div>
            {loading ? <div style={{color:"#475569",textAlign:"center",padding:40}}>⏳ {isEN?"Loading...":"Cargando..."}</div> : (
              <div style={{overflowX:"auto"}}>
                {visStrikes.map(strike=>{
                  const call=expiryOpts.find(o=>o.strike===strike&&o.type==="C");
                  const put =expiryOpts.find(o=>o.strike===strike&&o.type==="P");
                  const cOI=call?.oi||0, pOI=put?.oi||0;
                  const maxOI=Math.max(...visStrikes.map(s=>{
                    const c=expiryOpts.find(o=>o.strike===s&&o.type==="C");
                    const p=expiryOpts.find(o=>o.strike===s&&o.type==="P");
                    return Math.max(c?.oi||0,p?.oi||0);
                  }),1);
                  const isATM=spot&&Math.abs(strike-spot)/spot<0.01;
                  const isMP=maxPain===strike;
                  return (
                    <div key={strike} style={{display:"flex",alignItems:"center",gap:8,marginBottom:4,padding:"4px 0",borderBottom:"1px solid rgba(255,255,255,0.03)"}}>
                      <div style={{width:90,textAlign:"right",fontSize:11,fontWeight:isATM?800:isMP?700:500,
                        color:isATM?"#0066FF":isMP?"#a78bfa":"#94a3b8",flexShrink:0}}>
                        {isATM?"◆ ":isMP?"★ ":""}{fmtP(strike)}
                      </div>
                      {/* Calls bar (right) */}
                      <div style={{flex:1,display:"flex",justifyContent:"flex-end"}}>
                        <div style={{height:18,width:`${cOI/maxOI*100}%`,background:"linear-gradient(270deg,#22c55e,#15803d)",borderRadius:"3px 0 0 3px",minWidth:cOI>0?2:0,transition:"width 0.4s"}}/>
                      </div>
                      <div style={{width:1,background:"rgba(255,255,255,0.15)",height:18,flexShrink:0}}/>
                      {/* Puts bar (right) */}
                      <div style={{flex:1}}>
                        <div style={{height:18,width:`${pOI/maxOI*100}%`,background:"linear-gradient(90deg,#dc2626,#f87171)",borderRadius:"0 3px 3px 0",minWidth:pOI>0?2:0,transition:"width 0.4s"}}/>
                      </div>
                      <div style={{width:80,fontSize:10,color:"#f87171",textAlign:"right",flexShrink:0}}>{fmtOI(pOI)}</div>
                      <div style={{width:80,fontSize:10,color:"#22c55e",textAlign:"left",flexShrink:0}}>{fmtOI(cOI)}</div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ── MAX PAIN TAB ── */}
        {tab==="maxpain" && (
          <div>
            <div style={{marginBottom:20}}>
              <h3 style={{color:"#f1f5f9",fontWeight:800,fontSize:16,margin:"0 0 6px"}}>🎯 Max Pain — {selExpiry?fmtExp(selExpiry):""} ({selExpiry?daysToExpiry(selExpiry):0}d)</h3>
              <p style={{color:"#64748b",fontSize:13,margin:0,lineHeight:1.6}}>
                {isEN
                  ?"Max Pain is the price at which option buyers lose the most money at expiry. Market makers have an incentive to keep the price near this level."
                  :"Max Pain es el precio donde los compradores de opciones pierden más dinero al vencimiento. Los market makers tienen incentivo para mantener el precio cerca de este nivel."}
              </p>
            </div>
            {maxPain && spot && (
              <div style={{display:"flex",gap:16,marginBottom:24,flexWrap:"wrap"}}>
                {[
                  {label:"Max Pain Strike",val:fmtP(maxPain),color:"#a78bfa"},
                  {label:isEN?"Current Spot":"Spot Actual",val:fmtP(spot),color:asset.color},
                  {label:isEN?"Difference":"Diferencia",val:`${((maxPain-spot)/spot*100).toFixed(2)}%`,color:maxPain>spot?"#22c55e":"#f87171"},
                  {label:"DTE",val:`${daysToExpiry(selExpiry||"")} días`,color:"#f1f5f9"},
                ].map((m,i)=>(
                  <div key={i} style={{background:"#0d1627",border:"1px solid rgba(255,255,255,0.07)",borderRadius:12,padding:"14px 20px",flex:"1 1 120px"}}>
                    <div style={{fontSize:10,color:"#64748b",fontWeight:700,textTransform:"uppercase",letterSpacing:0.5,marginBottom:6}}>{m.label}</div>
                    <div style={{fontSize:20,fontWeight:800,color:m.color}}>{m.val}</div>
                  </div>
                ))}
              </div>
            )}
            {loading ? <div style={{color:"#475569",textAlign:"center",padding:40}}>⏳</div> : (
              <div style={{overflowX:"auto"}}>
                {visStrikes.map(strike=>{
                  // Calculate pain at this strike
                  let pain=0;
                  for(const s of strikes){
                    const c=expiryOpts.find(o=>o.strike===s&&o.type==="C");
                    const p=expiryOpts.find(o=>o.strike===s&&o.type==="P");
                    if(c&&strike>s) pain+=(strike-s)*c.oi;
                    if(p&&strike<s) pain+=(s-strike)*p.oi;
                  }
                  const maxPainVal=visStrikes.reduce((mx,ts)=>{
                    let p2=0;
                    for(const s of strikes){
                      const c=expiryOpts.find(o=>o.strike===s&&o.type==="C");
                      const pp=expiryOpts.find(o=>o.strike===s&&o.type==="P");
                      if(c&&ts>s) p2+=(ts-s)*c.oi;
                      if(pp&&ts<s) p2+=(s-ts)*pp.oi;
                    }
                    return Math.max(mx,p2);
                  },1);
                  const isMP=maxPain===strike;
                  const isATM=spot&&Math.abs(strike-spot)/spot<0.01;
                  return (
                    <div key={strike} style={{display:"flex",alignItems:"center",gap:8,marginBottom:3,padding:"3px 0"}}>
                      <div style={{width:100,textAlign:"right",fontSize:11,fontWeight:isMP?800:isATM?700:400,
                        color:isMP?"#a78bfa":isATM?"#0066FF":"#64748b",flexShrink:0}}>
                        {isMP?"★ ":isATM?"◆ ":""}{fmtP(strike)}
                      </div>
                      <div style={{flex:1,height:16,background:"rgba(255,255,255,0.04)",borderRadius:4,overflow:"hidden"}}>
                        <div style={{height:"100%",width:`${pain/maxPainVal*100}%`,
                          background:isMP?"linear-gradient(90deg,#7c3aed,#a78bfa)":isATM?"linear-gradient(90deg,#0070aa,#0066FF)":"linear-gradient(90deg,#334155,#475569)",
                          borderRadius:4,transition:"width 0.4s"}}/>
                      </div>
                      <div style={{width:80,fontSize:10,color:isMP?"#a78bfa":"#475569",textAlign:"right",flexShrink:0,fontFamily:"monospace"}}>
                        {(pain/1e6).toFixed(1)}M
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
            <div style={{marginTop:16,padding:"12px 16px",background:"rgba(167,139,250,0.07)",border:"1px solid rgba(167,139,250,0.2)",borderRadius:10,fontSize:12,color:"#94a3b8",lineHeight:1.6}}>
              💡 <strong style={{color:"#a78bfa"}}>{isEN?"Trading tip":"Consejo"}: </strong>
              {isEN
                ?"If spot is below max pain, expect upward pressure. If above, expect downward pressure as expiry approaches."
                :"Si el spot está por debajo del max pain, espera presión alcista. Si está por encima, presión bajista conforme se acerca el vencimiento."}
            </div>
          </div>
        )}

        {/* ── EXPIRATIONS TAB ── */}
        {tab==="expiries" && (
          <div>
            <div style={{marginBottom:16,fontSize:13,color:"#64748b"}}>{isEN?"Open interest and volume distribution across all expiration dates":"Distribución de open interest y volumen en todas las fechas de vencimiento"}</div>
            {loading ? <div style={{color:"#475569",textAlign:"center",padding:40}}>⏳</div> : (
              <table style={{width:"100%",borderCollapse:"collapse"}}>
                <thead>
                  <tr>
                    {[isEN?"Expiry":"Vencimiento","DTE",isEN?"Call OI":"OI Calls",isEN?"Put OI":"OI Puts",isEN?"Total OI":"OI Total","P/C",isEN?"24h Vol":"Vol 24h",isEN?"Bias":"Sesgo"].map(h=>(
                      <th key={h} style={thSt}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {expiries.map(exp=>{
                    const eo=allOpts.filter(o=>o.expiry===exp);
                    const cOI=eo.filter(o=>o.type==="C").reduce((s,o)=>s+o.oi,0);
                    const pOI=eo.filter(o=>o.type==="P").reduce((s,o)=>s+o.oi,0);
                    const tot=cOI+pOI;
                    const pc=cOI>0?(pOI/cOI).toFixed(2):"—";
                    const vol=eo.reduce((s,o)=>s+o.vol24h,0);
                    const dte=daysToExpiry(exp);
                    const bias=parseFloat(pc)<0.7?"🟢 Bull":parseFloat(pc)>1.2?"🔴 Bear":"🟡 Neutral";
                    const isSel=exp===selExpiry;
                    return (
                      <tr key={exp} onClick={()=>{setSelExpiry(exp);setTab("chain");}}
                        style={{cursor:"pointer",background:isSel?"rgba(0,102,255,0.08)":"transparent",transition:"background 0.1s"}}
                        onMouseEnter={e=>e.currentTarget.style.background=isSel?"rgba(0,102,255,0.12)":"rgba(255,255,255,0.03)"}
                        onMouseLeave={e=>e.currentTarget.style.background=isSel?"rgba(0,102,255,0.08)":"transparent"}>
                        <td style={{...tdSt,textAlign:"left",fontWeight:isSel?700:400,color:isSel?"#0066FF":"#f1f5f9"}}>{fmtExp(exp)}{isSel?" ◆":""}</td>
                        <td style={{...tdSt,color:dte<=7?"#f59e0b":dte<=30?"#94a3b8":"#64748b"}}>{dte}d</td>
                        <td style={{...tdSt,color:"#22c55e"}}>{fmtOI(cOI)}</td>
                        <td style={{...tdSt,color:"#f87171"}}>{fmtOI(pOI)}</td>
                        <td style={{...tdSt,fontWeight:600,color:"#f1f5f9"}}>{fmtOI(tot)}</td>
                        <td style={{...tdSt,color:parseFloat(pc)<0.7?"#22c55e":parseFloat(pc)>1.2?"#f87171":"#fbbf24"}}>{pc}</td>
                        <td style={{...tdSt,color:"#94a3b8"}}>{fmtVol(vol)}</td>
                        <td style={{...tdSt}}>{bias}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
            <div style={{marginTop:12,fontSize:11,color:"#475569"}}>
              💡 {isEN?"Click any row to view its options chain":"Haz clic en cualquier fila para ver su cadena de opciones"}
            </div>
          </div>
        )}

      </div>

      {/* ─ FOOTER ─ */}
      <div style={{maxWidth:1600,margin:"0 auto",padding:"0 24px"}}>
        <div style={{borderTop:"1px solid rgba(255,255,255,0.05)",paddingTop:14,display:"flex",flexWrap:"wrap",gap:12,alignItems:"center"}}>
          <span style={{fontSize:10,color:"#334155"}}>📡 {isEN?"Data":"Datos"}: Deribit Public API · {isEN?"Fear & Greed":"Miedo y Codicia"}: alternative.me</span>
          <span style={{fontSize:10,color:"#334155",marginLeft:"auto"}}>⚠️ {isEN?"For informational purposes only. Not financial advice.":"Solo informativo. No es consejo financiero."}</span>
        </div>
      </div>

    </div>
  );
}

