function AdvancedScreenerPage({ isPremium, onNeedPremium, lang }) {
  const isEN = lang === "en";
  const [tab,          setTab]         = useState("stocks");
  const [sortCol,      setSortCol]     = useState("score");
  const [sortDir,      setSortDir]     = useState(-1);
  const [search,       setSearch]      = useState("");
  const [minScore,     setMinScore]    = useState(0);
  const [filterPat,    setFilterPat]   = useState("Todos");
  const [filterMkt,    setFilterMkt]   = useState("Todos");
  const [minChg,       setMinChg]      = useState(-20);
  const [livePrices,   setLivePrices]  = useState({});
  const [lastUpdate,   setLastUpdate]  = useState(null);
  const [wsStatus,     setWsStatus]    = useState("connecting");
  const [alerts,       setAlerts2]     = useState([]);
  const [flashRows,    setFlashRows]   = useState({});
  const [refreshing,   setRefreshing]  = useState(false);
  const [selectedRow,  setSelectedRow] = useState(null); // mini AI panel
  const [savedFilters, setSavedFilters]= useState(null);
  const prevPrices     = useRef({});
  const alertedTickers = useRef({});
  const wsRef          = useRef(null);
  const FKEY = "d86clthr01qgiu44rtmgd86clthr01qgiu44rtn0";

  const ALL_TICKERS = useMemo(()=>{
    const s = new Set();
    Object.values(SCREENER_DATA).forEach(arr=>arr.forEach(r=>s.add(r.s)));
    return [...s];
  },[]);

  const fetchPricesREST = useCallback(async()=>{
    const tickers = ALL_TICKERS.slice(0,20);
    const results = {};
    await Promise.allSettled(tickers.map(async t=>{
      try{
        const r = await fetch(`https://finnhub.io/api/v1/quote?symbol=${t}&token=${FKEY}`);
        const d = await r.json();
        if(d.c && d.c > 0) results[t] = { price:d.c, change:d.dp??0, open:d.o, high:d.h, low:d.l, prev:d.pc };
      }catch(e){}
    }));
    setLivePrices(prev=>{
      const merged = {...prev};
      Object.entries(results).forEach(([t,v])=>{
        const prev2 = prevPrices.current[t]?.price;
        if(prev2 && v.price !== prev2){
          setFlashRows(f=>({...f,[t]:v.price>prev2?"up":"down"}));
          setTimeout(()=>setFlashRows(f=>{const n={...f};delete n[t];return n;}),700);
          const absChg = Math.abs(v.change);
          if(absChg>=2 && (!alertedTickers.current[t]||Date.now()-alertedTickers.current[t]>300000)){
            alertedTickers.current[t]=Date.now();
            const msg=`${t} ${v.change>=0?"+":""}${v.change?.toFixed(2)}% (${isEN?"big move":"movimiento detectado"})`;
            setAlerts2(a=>[{id:Date.now(),ticker:t,msg,chg:v.change,ts:new Date().toLocaleTimeString()},...a].slice(0,5));
            try{playAlertSound("price");}catch(e){}
          }
        }
        prevPrices.current[t]=v;
        merged[t]=v;
      });
      return merged;
    });
    setLastUpdate(new Date());
  },[ALL_TICKERS, isEN]);

  useEffect(()=>{
    if(!isPremium) return;
    let ws, retryTimer;
    const connect = ()=>{
      try{
        ws = new WebSocket(`wss://ws.finnhub.io?token=${FKEY}`);
        wsRef.current = ws;
        ws.onopen=()=>{
          setWsStatus("live");
          ALL_TICKERS.slice(0,15).forEach(t=>ws.send(JSON.stringify({type:"subscribe",symbol:t})));
        };
        ws.onmessage=e=>{
          try{
            const d=JSON.parse(e.data);
            if(d.type==="trade"&&d.data){
              d.data.forEach(trade=>{
                const t=trade.s, price=trade.p;
                if(!t||!price) return;
                setLivePrices(prev=>{
                  const prevP=prev[t]?.price, open=prev[t]?.open??price;
                  const chgPct=open>0?((price-open)/open)*100:0;
                  const newEntry={price,change:chgPct,open,high:Math.max(prev[t]?.high??0,price),low:Math.min(prev[t]?.low??9999,price)};
                  if(prevP&&price!==prevP){
                    setFlashRows(f=>({...f,[t]:price>prevP?"up":"down"}));
                    setTimeout(()=>setFlashRows(f=>{const n={...f};delete n[t];return n;}),600);
                    if(Math.abs(chgPct)>=2&&(!alertedTickers.current[t]||Date.now()-alertedTickers.current[t]>300000)){
                      alertedTickers.current[t]=Date.now();
                      setAlerts2(a=>[{id:Date.now(),ticker:t,msg:`${t} ${chgPct>=0?"+":""}${chgPct.toFixed(2)}%`,chg:chgPct,ts:new Date().toLocaleTimeString()},...a].slice(0,5));
                      try{playAlertSound("price");}catch(e2){}
                    }
                  }
                  prevPrices.current[t]=newEntry;
                  return {...prev,[t]:newEntry};
                });
                setLastUpdate(new Date());
              });
            }
          }catch(e){}
        };
        ws.onerror=()=>setWsStatus("polling");
        ws.onclose=()=>{setWsStatus("polling");retryTimer=setTimeout(connect,10000);};
      }catch(e){setWsStatus("polling");}
    };
    fetchPricesREST();
    connect();
    const pollTimer=setInterval(fetchPricesREST,30000);
    return()=>{clearInterval(pollTimer);clearTimeout(retryTimer);try{if(ws)ws.close();}catch(e){}};
  },[isPremium]);

  if(!isPremium) return(
    <div style={{maxWidth:700,margin:"60px auto",textAlign:"center",padding:"0 20px"}}>
      <div style={{fontSize:56,marginBottom:12}}>🔬</div>
      <h2 style={{color:C.text,fontWeight:800,fontSize:22,marginBottom:8}}>{isEN?"Advanced Screener":"Screener Avanzado"}</h2>
      <p style={{color:C.muted,fontSize:15,marginBottom:24,lineHeight:1.6}}>
        {isEN?"Scan stocks, options, intraday and scalping with AI signals. PREMIUM exclusive.":"Escanea acciones, opciones, intraday y scalping con señales IA. Exclusivo PREMIUM."}
      </p>
      <button onClick={onNeedPremium} style={{background:"linear-gradient(135deg,#F59E0B,#6366F1)",color:"#fff",border:"none",borderRadius:12,padding:"14px 36px",fontWeight:800,fontSize:16,cursor:"pointer",boxShadow:"0 4px 20px rgba(139,92,246,0.4)"}}>
        ✦ {isEN?"Unlock PREMIUM":"Desbloquear PREMIUM"}
      </button>
    </div>
  );

  const tabs=[
    {id:"stocks",  l:"📊 "+(isEN?"Stocks":"Acciones")},
    {id:"options", l:"⚡ "+(isEN?"Options":"Opciones")},
    {id:"intraday",l:"🕐 Intraday"},
    {id:"scalping",l:"⚡ Scalping"},
  ];

  const mergedData=(SCREENER_DATA[tab]||[]).map(r=>{
    const live=livePrices[r.s];
    return{...r, p:live?.price??r.p, chg:live?.change??r.chg, liveHigh:live?.high, liveLow:live?.low};
  });

  const PATTERNS_AVAILABLE=[...new Set((SCREENER_DATA.stocks||[]).map(r=>r.pattern))];
  const MKT_RANGES=["Todos","< $100B","$100B–$1T","$1T+"];

  const matchMkt=(mkt)=>{
    if(filterMkt==="Todos") return true;
    const raw=mkt?.replace(/[$TB]/g,"");
    const v=parseFloat(raw)||0;
    const isT=mkt?.includes("T"), isB=mkt?.includes("B");
    const valB=isT?v*1000:v;
    if(filterMkt==="< $100B") return valB<100;
    if(filterMkt==="$100B–$1T") return valB>=100&&valB<1000;
    if(filterMkt==="$1T+") return valB>=1000;
    return true;
  };

  const data=mergedData.filter(r=>{
    if(search&&!r.s.toLowerCase().includes(search.toLowerCase())&&!r.n?.toLowerCase().includes(search.toLowerCase())) return false;
    if(r.score<minScore) return false;
    if(tab==="stocks"&&filterPat!=="Todos"&&r.pattern!==filterPat) return false;
    if(tab==="stocks"&&!matchMkt(r.mkt)) return false;
    if(tab==="stocks"&&r.chg<minChg) return false;
    return true;
  }).sort((a,b)=>{
    const av=a[sortCol]??0, bv=b[sortCol]??0;
    return(av>bv?1:av<bv?-1:0)*sortDir;
  });

  const allRows=Object.values(SCREENER_DATA).flat().map(r=>{
    const live=livePrices[r.s];
    return{...r, chg:live?.change??r.chg};
  });
  const topGainers=[...allRows].sort((a,b)=>b.chg-a.chg).slice(0,3);
  const topLosers =[...allRows].sort((a,b)=>a.chg-b.chg).slice(0,3);

  const scoreColor=s=>s>=90?"#10B981":s>=75?"#0066FF":"#94A3B8";
  const chgColor  =c=>c>=0?"#10B981":"#EF4444";
  const chgBg     =c=>c>=2?"rgba(16,185,129,0.12)":c<=-2?"rgba(239,68,68,0.12)":"transparent";
  const rsiColor  =r=>r>=70?"#EF4444":r<=30?"#10B981":"#94A3B8";

  const sortToggle=col=>{if(sortCol===col)setSortDir(d=>-d);else{setSortCol(col);setSortDir(-1);}};
  const SortBtn=({col,label})=>(
    <button onClick={()=>sortToggle(col)} style={{background:"none",border:"none",color:sortCol===col?"#FCD34D":C.muted,cursor:"pointer",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:0.8,padding:0,fontFamily:"inherit",display:"flex",alignItems:"center",gap:2,whiteSpace:"nowrap"}}>
      {label}{sortCol===col?(sortDir===-1?" ▼":" ▲"):""}
    </button>
  );

  // Export CSV
  const exportCSV=()=>{
    const rows=[["Ticker","Empresa","Precio","Chg%","RSI","Volumen","Mkt Cap","Patrón","Score"].join(","),
      ...data.map(r=>[r.s,r.n,r.p?.toFixed(2),r.chg?.toFixed(2),r.rsi||"",r.vol||"",r.mkt||"",r.pattern||"",r.score].join(","))];
    const a=document.createElement("a");
    a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(rows.join("\n"));
    a.download=`nexotrade_screener_${new Date().toISOString().slice(0,10)}.csv`;
    a.click();
  };

  return(
    <div style={{maxWidth:1180,margin:"0 auto",padding:"0 12px 60px"}}>

      {/* Alert toasts */}
      {alerts.length>0&&(
        <div style={{position:"fixed",top:72,right:16,zIndex:9999,display:"flex",flexDirection:"column",gap:8,maxWidth:320}}>
          {alerts.map(a=>(
            <div key={a.id} style={{background:a.chg>=0?"rgba(16,185,129,0.95)":"rgba(239,68,68,0.95)",color:"#fff",borderRadius:12,padding:"10px 14px",fontSize:13,fontWeight:700,boxShadow:"0 4px 20px rgba(0,0,0,0.4)",display:"flex",alignItems:"center",gap:8,cursor:"pointer"}}
              onClick={()=>setAlerts2(x=>x.filter(i=>i.id!==a.id))}>
              <span style={{fontSize:18}}>{a.chg>=0?"🚀":"⚠️"}</span>
              <div><div>{a.msg}</div><div style={{fontSize:10,opacity:0.8}}>{a.ts} · clic para cerrar</div></div>
            </div>
          ))}
        </div>
      )}

      {/* ── MINI AI PANEL (slide-in) ── */}
      {selectedRow&&(
        <div style={{position:"fixed",top:0,right:0,bottom:0,width:340,zIndex:9980,background:C.card,borderLeft:`1px solid ${C.border}`,boxShadow:"-8px 0 40px rgba(0,0,0,0.4)",display:"flex",flexDirection:"column",overflow:"hidden"}}>
          <div style={{background:"linear-gradient(135deg,rgba(0,102,255,0.10),rgba(0,102,255,0.04))",borderBottom:`1px solid ${C.border}`,padding:"16px 20px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
            <div>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <span style={{fontFamily:"monospace",fontWeight:900,fontSize:20,color:"#FCD34D"}}>${selectedRow.s}</span>
                <span style={{fontSize:11,background:"rgba(0,102,255,0.14)",color:"#0066FF",border:"1px solid rgba(0,102,255,0.3)",borderRadius:6,padding:"2px 7px",fontWeight:700}}>
                  {PATTERN_ICON[selectedRow.pattern]||"📊"} {selectedRow.pattern}
                </span>
              </div>
              <div style={{fontSize:12,color:C.muted,marginTop:2}}>{selectedRow.n}</div>
            </div>
            <button onClick={()=>setSelectedRow(null)} style={{background:"rgba(255,255,255,0.05)",border:`1px solid ${C.border}`,borderRadius:8,width:32,height:32,cursor:"pointer",color:C.muted,fontSize:16,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
          </div>
          <div style={{flex:1,overflowY:"auto",padding:"20px"}}>
            {/* Price + RSI */}
            <div className="nexo-radar-detail-stats" style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:16}}>
              {[
                {l:"Precio",v:`$${selectedRow.p?.toFixed(2)}`,c:C.text},
                {l:"Cambio",v:`${selectedRow.chg>=0?"+":""}${selectedRow.chg?.toFixed(2)}%`,c:chgColor(selectedRow.chg)},
                {l:"RSI",v:selectedRow.rsi||"—",c:rsiColor(selectedRow.rsi||50)},
              ].map((item,i)=>(
                <div key={i} style={{background:C.card2,border:`1px solid ${C.border}`,borderRadius:10,padding:"10px",textAlign:"center"}}>
                  <div style={{fontSize:10,color:C.muted,marginBottom:4}}>{item.l}</div>
                  <div style={{fontSize:15,fontWeight:900,color:item.c}}>{item.v}</div>
                </div>
              ))}
            </div>

            {/* Setup IA */}
            {(()=>{const {ent,sl,tp}=calcSetup(selectedRow.p,selectedRow.chg);return(
              <div style={{background:"rgba(139,92,246,0.08)",border:"1px solid rgba(139,92,246,0.2)",borderRadius:12,padding:"14px",marginBottom:16}}>
                <div style={{fontSize:11,fontWeight:700,color:"#FCD34D",letterSpacing:0.5,marginBottom:10}}>🤖 SETUP IA</div>
                <div className="nexo-radar-detail-stats2" style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8}}>
                  {[{l:"ENT",v:`$${ent}`,c:"#F59E0B"},{l:"SL",v:`$${sl}`,c:"#EF4444"},{l:"TP",v:`$${tp}`,c:"#10B981"}].map((s,i)=>(
                    <div key={i} style={{textAlign:"center"}}>
                      <div style={{fontSize:10,color:C.muted,marginBottom:3}}>{s.l}</div>
                      <div style={{fontSize:14,fontWeight:800,color:s.c,fontFamily:"monospace"}}>{s.v}</div>
                    </div>
                  ))}
                </div>
                <div style={{marginTop:10,fontSize:11,color:C.muted,display:"flex",justifyContent:"space-between"}}>
                  <span>R/R Ratio: <strong style={{color:"#10B981"}}>{((Math.abs(calcSetup(selectedRow.p,selectedRow.chg).tp-selectedRow.p)/Math.abs(calcSetup(selectedRow.p,selectedRow.chg).sl-selectedRow.p))||0).toFixed(1)}:1</strong></span>
                  <span>Risk: <strong style={{color:"#EF4444"}}>-{(Math.abs(calcSetup(selectedRow.p,selectedRow.chg).sl-selectedRow.p)/selectedRow.p*100).toFixed(1)}%</strong></span>
                </div>
              </div>
            );})()}

            {/* AI Analysis */}
            <div style={{background:C.card2,border:`1px solid ${C.border}`,borderRadius:12,padding:"14px",marginBottom:16}}>
              <div style={{fontSize:11,fontWeight:700,color:"#0066FF",letterSpacing:0.5,marginBottom:8}}>🧠 ANÁLISIS IA</div>
              <p style={{fontSize:13,color:C.muted,lineHeight:1.6,margin:0}}>
                {(AI_ANALYSIS[selectedRow.pattern]||((r)=>`$${r.s} muestra señal ${r.pattern}. RSI ${r.rsi||"N/A"}, volumen ${r.vol||"N/A"}. Score IA: ${r.score}/100.`))(selectedRow)}
              </p>
            </div>

            {/* Score bar */}
            <div style={{background:C.card2,border:`1px solid ${C.border}`,borderRadius:12,padding:"14px",marginBottom:16}}>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
                <span style={{fontSize:11,fontWeight:700,color:C.muted}}>SCORE IA</span>
                <span style={{fontSize:14,fontWeight:900,color:scoreColor(selectedRow.score)}}>{selectedRow.score}/100</span>
              </div>
              <div style={{background:"rgba(255,255,255,0.06)",borderRadius:999,height:8,overflow:"hidden"}}>
                <div style={{width:`${selectedRow.score}%`,height:"100%",background:`linear-gradient(90deg,${scoreColor(selectedRow.score)},${scoreColor(selectedRow.score)}aa)`,borderRadius:999,transition:"width 0.5s"}}/>
              </div>
              <div style={{fontSize:11,color:scoreColor(selectedRow.score),marginTop:6,fontWeight:700,textAlign:"right"}}>
                {selectedRow.score>=90?"⭐ Excelente":selectedRow.score>=75?"👍 Muy bueno":selectedRow.score>=60?"📊 Bueno":"⚠️ Precaución"}
              </div>
            </div>

            {/* TradingView link */}
            <a href={`https://www.tradingview.com/chart/?symbol=${selectedRow.s}&aff_id=167149`} target="_blank" rel="noopener noreferrer"
              style={{display:"block",background:"linear-gradient(135deg,#2962FF,#2962FFcc)",borderRadius:10,padding:"10px",color:"#fff",fontSize:13,fontWeight:700,textAlign:"center",textDecoration:"none",marginBottom:8}}>
              📊 Ver en TradingView →
            </a>
          </div>
        </div>
      )}

      {/* ── HEADER ── */}
      <div style={{background:"linear-gradient(135deg,rgba(139,92,246,0.08),rgba(99,102,241,0.04))",border:"1px solid rgba(139,92,246,0.2)",borderRadius:20,padding:"20px 24px",marginBottom:20,position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",top:0,left:0,right:0,height:2,background:"linear-gradient(90deg,#F59E0B,#6366F1,#00e58f)"}}/>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:12}}>
          <div>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:4}}>
              <span style={{fontSize:22,fontWeight:900,color:C.text,letterSpacing:"-0.5px"}}>🔬 {isEN?"Advanced Screener":"Screener Avanzado"}</span>
              <span style={{background:"linear-gradient(135deg,#F59E0B,#6366F1)",color:"#fff",fontSize:10,fontWeight:800,padding:"3px 8px",borderRadius:6,letterSpacing:0.5}}>PREMIUM</span>
              <div style={{display:"flex",alignItems:"center",gap:5,background:"rgba(16,185,129,0.1)",border:"1px solid rgba(16,185,129,0.3)",borderRadius:20,padding:"3px 10px"}}>
                <div style={{width:7,height:7,borderRadius:"50%",background:wsStatus==="live"?"#10B981":"#F59E0B",animation:"pulse 1.5s infinite"}}/>
                <span style={{fontSize:10,fontWeight:800,color:wsStatus==="live"?"#10B981":"#F59E0B",letterSpacing:0.5}}>{wsStatus==="live"?"LIVE":"AUTO"}</span>
              </div>
            </div>
            <p style={{color:C.muted,fontSize:12,margin:0}}>
              {isEN?"Real-time scanner · AI-powered signals · Institutional grade":"Scanner en tiempo real · Señales IA · Grado institucional"}
              {lastUpdate&&<span style={{color:C.muted2,marginLeft:8}}>· {isEN?"Updated":"Actualizado"} {lastUpdate.toLocaleTimeString()}</span>}
            </p>
          </div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <button onClick={()=>setSavedFilters({search,minScore,filterPat,filterMkt,minChg})}
              style={{background:"rgba(139,92,246,0.12)",border:"1px solid rgba(139,92,246,0.3)",color:"#FCD34D",borderRadius:10,padding:"8px 14px",fontSize:12,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:5}}>
              💾 {isEN?"Save filters":"Guardar filtros"}
            </button>
            <button onClick={exportCSV}
              style={{background:"rgba(16,185,129,0.12)",border:"1px solid rgba(16,185,129,0.3)",color:"#10B981",borderRadius:10,padding:"8px 14px",fontSize:12,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:5}}>
              ⬇️ {isEN?"Export CSV":"Exportar CSV"}
            </button>
            <button onClick={async()=>{setRefreshing(true);await fetchPricesREST();setRefreshing(false);}} disabled={refreshing}
              style={{background:refreshing?"rgba(139,92,246,0.25)":"rgba(139,92,246,0.15)",border:"1px solid rgba(139,92,246,0.3)",color:"#FCD34D",borderRadius:10,padding:"8px 14px",fontSize:12,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:5,opacity:refreshing?0.7:1}}>
              {refreshing?"⏳":"↻"} {refreshing?(isEN?"Updating...":"Actualizando..."):(isEN?"Refresh":"Actualizar")}
            </button>
          </div>
        </div>
      </div>

      {/* ── TOP MOVERS ── */}
      <div className="nexo-top-movers" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:16}}>
        <div style={{background:C.card,border:"1px solid rgba(16,185,129,0.2)",borderRadius:14,padding:"12px 16px"}}>
          <div style={{fontSize:11,fontWeight:700,color:"#10B981",letterSpacing:0.5,marginBottom:8}}>🚀 TOP GAINERS</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {topGainers.map(r=>(
              <div key={r.s} style={{background:"rgba(16,185,129,0.1)",border:"1px solid rgba(16,185,129,0.2)",borderRadius:8,padding:"4px 10px",fontSize:12}}>
                <span style={{fontWeight:800,color:"#10B981",fontFamily:"monospace"}}>{r.s}</span>
                <span style={{color:"#10B981",marginLeft:4,fontWeight:700}}>+{r.chg?.toFixed(2)}%</span>
              </div>
            ))}
          </div>
        </div>
        <div style={{background:C.card,border:"1px solid rgba(239,68,68,0.2)",borderRadius:14,padding:"12px 16px"}}>
          <div style={{fontSize:11,fontWeight:700,color:"#EF4444",letterSpacing:0.5,marginBottom:8}}>📉 TOP LOSERS</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {topLosers.map(r=>(
              <div key={r.s} style={{background:"rgba(239,68,68,0.1)",border:"1px solid rgba(239,68,68,0.2)",borderRadius:8,padding:"4px 10px",fontSize:12}}>
                <span style={{fontWeight:800,color:"#EF4444",fontFamily:"monospace"}}>{r.s}</span>
                <span style={{color:"#EF4444",marginLeft:4,fontWeight:700}}>{r.chg?.toFixed(2)}%</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ── TABS ── */}
      <div style={{display:"flex",gap:0,background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:4,marginBottom:14,width:"fit-content"}}>
        {tabs.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)}
            style={{padding:"8px 18px",borderRadius:9,border:"none",background:tab===t.id?"linear-gradient(135deg,#F59E0B,#6366F1)":"transparent",color:tab===t.id?"#fff":C.muted,fontSize:13,fontWeight:tab===t.id?700:500,cursor:"pointer",transition:"all 0.2s"}}>
            {t.l}
          </button>
        ))}
      </div>

      {/* ── FILTERS ── */}
      <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap",alignItems:"center"}}>
        <input value={search} onChange={e=>setSearch(e.target.value)}
          placeholder={isEN?"Search ticker…":"Buscar ticker…"}
          style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:"7px 12px",color:C.text,fontSize:13,outline:"none",fontFamily:"inherit",width:150}}/>

        {tab==="stocks"&&<>
          {/* SCORE */}
          <div style={{display:"flex",alignItems:"center",gap:6,background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:"5px 12px"}}>
            <span style={{fontSize:11,color:C.muted}}>Score ≥</span>
            <input type="range" min="0" max="95" step="5" value={minScore} onChange={e=>setMinScore(Number(e.target.value))} style={{width:70,accentColor:"#F59E0B"}}/>
            <span style={{fontSize:12,fontWeight:700,color:"#F59E0B",minWidth:22}}>{minScore}</span>
          </div>
          {/* CAMBIO % */}
          <div style={{display:"flex",alignItems:"center",gap:6,background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:"5px 12px"}}>
            <span style={{fontSize:11,color:C.muted}}>Chg ≥</span>
            <input type="range" min="-20" max="20" step="1" value={minChg} onChange={e=>setMinChg(Number(e.target.value))} style={{width:70,accentColor:"#F59E0B"}}/>
            <span style={{fontSize:12,fontWeight:700,color:minChg>=0?"#10B981":"#EF4444",minWidth:30}}>{minChg}%</span>
          </div>
          {/* PATRÓN */}
          <select value={filterPat} onChange={e=>setFilterPat(e.target.value)}
            style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:"7px 10px",color:C.text,fontSize:12,fontFamily:"inherit",cursor:"pointer",outline:"none"}}>
            <option value="Todos">Patrón: Todos</option>
            {PATTERNS_AVAILABLE.map(p=><option key={p} value={p}>{PATTERN_ICON[p]||"📊"} {p}</option>)}
          </select>
          {/* MKT CAP */}
          <select value={filterMkt} onChange={e=>setFilterMkt(e.target.value)}
            style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:"7px 10px",color:C.text,fontSize:12,fontFamily:"inherit",cursor:"pointer",outline:"none"}}>
            {MKT_RANGES.map(m=><option key={m} value={m}>Mkt Cap: {m}</option>)}
          </select>
        </>}

        <div style={{marginLeft:"auto",color:C.muted,fontSize:12}}>
          <span style={{fontWeight:700,color:C.text}}>{data.length}</span> {isEN?"results":"resultados"}
        </div>
      </div>

      {/* ── TABLE ── */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:16,boxShadow:C.shadow,overflowX:"auto",WebkitOverflowScrolling:"touch"}}>
        <div style={{minWidth:1100}}>

          {/* Stocks header */}
          {tab==="stocks"&&(
            <div style={{display:"grid",gridTemplateColumns:"80px 100px 105px 85px 65px 95px 105px 130px 1fr 72px 88px",padding:"9px 16px",background:C.card2,borderBottom:`1px solid ${C.border}`,gap:10,alignItems:"center"}}>
              {[["s","Ticker"],["spark","Tendencia"],["p","Precio"],["chg","Chg%"],["rsi","RSI"],["vol","Volumen"],["mkt","Mkt Cap"],["pattern","Patrón"],["setup","Setup IA"],["score","Score"],["actions",""]].map(([col,lbl])=>(
                col==="spark"||col==="setup"||col==="actions"
                  ? <span key={col} style={{fontSize:10,fontWeight:700,color:C.muted2,textTransform:"uppercase",letterSpacing:0.8}}>{lbl}</span>
                  : <SortBtn key={col} col={col} label={lbl}/>
              ))}
            </div>
          )}
          {tab==="options"&&(
            <div style={{display:"grid",gridTemplateColumns:"70px 160px 90px 80px 70px 80px 80px 72px",padding:"9px 14px",background:C.card2,borderBottom:`1px solid ${C.border}`,gap:8}}>
              {[["s","Ticker"],["n","Contrato"],["strike","Strike"],["exp","Vto"],["iv","IV"],["vol","Vol"],["chg","Chg%"],["score","Score"]].map(([col,lbl])=>(<SortBtn key={col} col={col} label={lbl}/>))}
            </div>
          )}
          {tab==="intraday"&&(
            <div style={{display:"grid",gridTemplateColumns:"70px 160px 95px 78px 62px 68px 120px 100px 72px",padding:"9px 14px",background:C.card2,borderBottom:`1px solid ${C.border}`,gap:8}}>
              {[["s","Ticker"],["n","Nombre"],["p","Price"],["chg","Chg%"],["atr","ATR"],["rvol","RVol"],["pattern","Pattern"],["signal","Signal"],["score","Score"]].map(([col,lbl])=>(<SortBtn key={col} col={col} label={lbl}/>))}
            </div>
          )}
          {tab==="scalping"&&(
            <div style={{display:"grid",gridTemplateColumns:"70px 160px 95px 90px 88px 68px 140px 72px",padding:"9px 14px",background:C.card2,borderBottom:`1px solid ${C.border}`,gap:8}}>
              {[["s","Ticker"],["n","Nombre"],["p","Price"],["spread","Spread"],["trades","Ops/hr"],["tf","TF"],["pattern","Setup"],["score","Score"]].map(([col,lbl])=>(<SortBtn key={col} col={col} label={lbl}/>))}
            </div>
          )}

          {/* Rows */}
          {data.map((r,i)=>{
            const flash=flashRows[r.s];
            const rowBg=flash==="up"?"rgba(16,185,129,0.15)":flash==="down"?"rgba(239,68,68,0.15)":chgBg(r.chg);
            const {ent,sl,tp}=calcSetup(r.p,r.chg);
            const isSelected=selectedRow?.s===r.s;
            return(
              <div key={i} style={{display:"grid",
                gridTemplateColumns:tab==="stocks"?"80px 100px 105px 85px 65px 95px 105px 130px 1fr 72px 88px":
                  tab==="options"?"70px 160px 90px 80px 70px 80px 80px 72px":
                  tab==="intraday"?"70px 160px 95px 78px 62px 68px 120px 100px 72px":
                  "70px 160px 95px 90px 88px 68px 140px 72px",
                padding:"9px 14px",borderBottom:`1px solid ${C.border}`,gap:8,
                transition:"background 0.25s",background:isSelected?"rgba(0,102,255,0.10)":rowBg,
                cursor:"default",alignItems:"center"}}
                onMouseEnter={e=>{if(!flash&&!isSelected)e.currentTarget.style.background="rgba(0,102,255,0.05)";}}
                onMouseLeave={e=>{if(!flash&&!isSelected)e.currentTarget.style.background=rowBg;}}>

                {/* Ticker */}
                <span style={{fontFamily:"monospace",fontWeight:800,color:"#00e58f",fontSize:13,letterSpacing:0.3}}>{r.s}</span>

                {tab==="stocks"&&<>
                  {/* Sparkline */}
                  <div><Sparkline points={r.spark} chg={r.chg} width={80} height={26}/></div>
                  {/* Precio */}
                  <span style={{fontSize:13,fontWeight:800,color:C.text,fontFamily:"monospace"}}>${r.p?.toFixed(2)}</span>
                  {/* Chg% */}
                  <span style={{fontSize:12,fontWeight:800,color:chgColor(r.chg),background:chgBg(r.chg),borderRadius:5,padding:"1px 4px"}}>{r.chg>=0?"+":""}{r.chg?.toFixed(2)}%</span>
                  {/* RSI */}
                  <span style={{fontSize:12,fontWeight:800,color:rsiColor(r.rsi||50),background:`${rsiColor(r.rsi||50)}18`,borderRadius:6,padding:"2px 5px",textAlign:"center"}}>{r.rsi||"—"}</span>
                  {/* Vol */}
                  <span style={{fontSize:11,color:C.muted}}>{r.vol}</span>
                  {/* Mkt */}
                  <span style={{fontSize:11,color:C.muted}}>{r.mkt}</span>
                  {/* Patrón */}
                  <span style={{fontSize:11,background:"rgba(0,102,255,0.14)",color:"#0066FF",border:"1px solid rgba(0,102,255,0.3)",borderRadius:6,padding:"2px 6px",whiteSpace:"nowrap",display:"flex",alignItems:"center",gap:4}}>
                    {PATTERN_ICON[r.pattern]||"📊"} {r.pattern}
                  </span>
                  {/* Setup IA */}
                  <div style={{fontSize:10,lineHeight:1.6}}>
                    <div><span style={{color:"#F59E0B",fontWeight:700}}>ENT</span> <span style={{color:C.text,fontFamily:"monospace"}}>${ent}</span></div>
                    <div><span style={{color:"#EF4444",fontWeight:700}}>SL</span>{"  "}<span style={{color:C.text,fontFamily:"monospace"}}>${sl}</span></div>
                    <div><span style={{color:"#10B981",fontWeight:700}}>TP</span>{"  "}<span style={{color:C.text,fontFamily:"monospace"}}>${tp}</span></div>
                  </div>
                </>}

                {tab==="options"&&<>
                  <span style={{fontSize:11,color:C.muted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.n}</span>
                  <span style={{fontSize:12,fontWeight:700,color:C.text,fontFamily:"monospace"}}>{r.strike}</span>
                  <span style={{fontSize:11,color:C.muted}}>{r.exp}</span>
                  <span style={{fontSize:12,color:"#F59E0B",fontWeight:800}}>{r.iv}</span>
                  <span style={{fontSize:11,color:C.muted}}>{r.vol}</span>
                  <span style={{fontSize:12,fontWeight:800,color:chgColor(r.chg)}}>{r.chg>=0?"+":""}{r.chg?.toFixed(2)}%</span>
                </>}

                {tab==="intraday"&&<>
                  <span style={{fontSize:12,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.n}</span>
                  <span style={{fontSize:13,fontWeight:800,color:C.text,fontFamily:"monospace"}}>${r.p?.toFixed(2)}</span>
                  <span style={{fontSize:12,fontWeight:800,color:chgColor(r.chg)}}>{r.chg>=0?"+":""}{r.chg?.toFixed(2)}%</span>
                  <span style={{fontSize:11,color:C.muted}}>{r.atr}</span>
                  <span style={{fontSize:12,fontWeight:700,color:"#F59E0B"}}>{r.rvol}</span>
                  <span style={{fontSize:11,background:"rgba(0,102,255,0.14)",color:"#0066FF",border:"1px solid rgba(0,102,255,0.3)",borderRadius:6,padding:"2px 7px",whiteSpace:"nowrap"}}>
                    {PATTERN_ICON[r.pattern]||"📊"} {r.pattern}
                  </span>
                  <span style={{fontSize:11,fontWeight:700,color:r.signal?.includes("Long")?"#10B981":"#EF4444"}}>{r.signal}</span>
                </>}

                {tab==="scalping"&&<>
                  <span style={{fontSize:12,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.n}</span>
                  <span style={{fontSize:13,fontWeight:800,color:C.text,fontFamily:"monospace"}}>${r.p?.toFixed(2)}</span>
                  <span style={{fontSize:12,color:C.text}}>{r.spread}</span>
                  <span style={{fontSize:11,color:C.muted}}>{r.trades}</span>
                  <span style={{fontSize:12,fontWeight:700,color:C.accent}}>{r.tf}</span>
                  <span style={{fontSize:11,background:"rgba(0,102,255,0.14)",color:"#0066FF",border:"1px solid rgba(0,102,255,0.3)",borderRadius:6,padding:"2px 7px",whiteSpace:"nowrap"}}>
                    {PATTERN_ICON[r.pattern]||"📊"} {r.pattern}
                  </span>
                </>}

                {/* Score ring */}
                <div style={{display:"flex",alignItems:"center",justifyContent:"center"}}>
                  <div style={{width:32,height:32,borderRadius:"50%",border:`2.5px solid ${scoreColor(r.score)}`,background:`${scoreColor(r.score)}18`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:900,color:scoreColor(r.score)}}>{r.score}</div>
                </div>

                {/* Actions — solo stocks */}
                {tab==="stocks"&&(
                  <div style={{display:"flex",gap:4,justifyContent:"center"}}>
                    <button onClick={()=>setSelectedRow(isSelected?null:r)}
                      style={{background:isSelected?"rgba(0,102,255,0.3)":"rgba(0,102,255,0.12)",border:"1px solid rgba(0,102,255,0.3)",borderRadius:7,padding:"4px 8px",color:isSelected?"#fff":"#0066FF",fontSize:11,fontWeight:700,cursor:"pointer",whiteSpace:"nowrap"}}>
                      👁 Ver
                    </button>
                    <button onClick={()=>{
                      setAlerts2(a=>[{id:Date.now(),ticker:r.s,msg:`🔔 Alerta creada: $${r.s} @ $${r.p?.toFixed(0)}`,chg:r.chg,ts:new Date().toLocaleTimeString()},...a].slice(0,5));
                    }} style={{background:"rgba(245,158,11,0.1)",border:"1px solid rgba(245,158,11,0.2)",borderRadius:7,padding:"4px 7px",color:"#F59E0B",fontSize:12,cursor:"pointer"}}>🔔</button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Footer hint */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:"12px 16px",marginTop:12,display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
        <span style={{fontSize:16}}>🔔</span>
        <span style={{fontSize:12,color:C.muted,flex:1}}>
          {isEN?"Auto-alert when stock moves ≥2% · Click 👁 Ver for AI analysis · Updates every 30s":"Alerta automática ≥2% · Clic en 👁 Ver para análisis IA · Se actualiza cada 30s"}
        </span>
        <span style={{fontSize:11,fontWeight:700,color:wsStatus==="live"?"#10B981":"#F59E0B"}}>
          {wsStatus==="live"?"● WebSocket LIVE":"● REST 30s"}
        </span>
      </div>

      <p style={{color:C.muted,fontSize:11,marginTop:10,textAlign:"center"}}>
        {isEN?"Signals are educational, not financial advice.":"Las señales son educativas, no son consejos financieros. NexoTrade no es asesor financiero."}
      </p>
    </div>
  );
}

// ── LEGAL PAGE WRAPPER ────────────────────────────────────────────────────────
function LegalPage({title, children, onBack, lang}){
  return(
    <div style={{maxWidth:760,margin:"0 auto",padding:"0 4px 40px"}}>
      <button onClick={onBack} style={{display:"flex",alignItems:"center",gap:6,background:"none",border:"none",color:C.muted,fontSize:13,cursor:"pointer",marginBottom:20,padding:"4px 0",fontFamily:"inherit"}}
        onMouseEnter={e=>e.currentTarget.style.color=C.accent}
        onMouseLeave={e=>e.currentTarget.style.color=C.muted}>
        ← {lang==="en"?"Back":"Volver"}
      </button>
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:20,padding:"32px 36px",boxShadow:C.shadow}}>
        <h1 style={{fontSize:24,fontWeight:900,color:C.text,marginBottom:6,letterSpacing:"-0.5px"}}>{title}</h1>
        <div style={{fontSize:11,color:C.muted2,marginBottom:28}}>{lang==="en"?"Last updated: May 2026":"Última actualización: Mayo 2026"} · nexotradeia.com</div>
        <div style={{color:C.muted,fontSize:14,lineHeight:1.8}}>{children}</div>
      </div>
    </div>
  );
}

function LegalSection({title,children}){
  return(
    <div style={{marginBottom:24}}>
      <h2 style={{fontSize:16,fontWeight:800,color:"var(--c-text)",marginBottom:10,paddingBottom:6,borderBottom:"1px solid var(--c-border)"}}>{title}</h2>
      {children}
    </div>
  );
}

// ── ALERT CENTER PAGE (page 42) ───────────────────────────────────────────────
const FINNHUB_KEY_ALERT = "d86clthr01qgiu44rtmgd86clthr01qgiu44rtn0";
const ALERT_STORAGE_KEY = "nx-price-alerts-v2";

function AlertCenterPage({ lang="es", user, onNeedAuth }) {
  const isEN = lang === "en";

  // ── State ─────────────────────────────────────────────────────────────────
  const [alerts, setAlerts] = useState(() => {
    try { return JSON.parse(localStorage.getItem(ALERT_STORAGE_KEY) || "[]"); } catch { return []; }
  });
  const [ticker,    setTicker]    = useState("");
  const [price,     setPrice]     = useState("");
  const [direction, setDirection] = useState("above"); // "above" | "below"
  const [checking,  setChecking]  = useState(false);
  const [lastCheck, setLastCheck] = useState(null);
  const [notifPerm, setNotifPerm] = useState(() => {
    if(typeof Notification !== "undefined") return Notification.permission;
    return "default";
  });
  const [fired, setFired] = useState({}); // {alertId: true} transient in-session
  const [liveMap, setLiveMap] = useState({}); // {TICKER: currentPrice} for proximity bars
  const [portfolioTickers, setPortfolioTickers] = useState([]); // smart suggestions

  // ── Persist ───────────────────────────────────────────────────────────────
  useEffect(() => {
    localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify(alerts));
  }, [alerts]);

  // ── Read portfolio tickers for smart suggestions ──────────────────────────
  useEffect(() => {
    try {
      const key = `nexo_portfolio_${user?.id||"guest"}`;
      const data = JSON.parse(localStorage.getItem(key) || "[]");
      const ticks = [...new Set(data.map(p => (p.ticker||p.symbol||"").toUpperCase()).filter(Boolean))];
      setPortfolioTickers(ticks);
    } catch{}
  }, [user?.id]);

  // ── Request notification permission ───────────────────────────────────────
  const requestPermission = async () => {
    if (typeof Notification === "undefined") return;
    const perm = await Notification.requestPermission();
    setNotifPerm(perm);
    if (perm === "granted") {
      new Notification("🔔 NexoTrade Alertas", {
        body: isEN ? "You will receive price alerts here." : "Recibirás alertas de precio aquí.",
        icon: "/logo_nexo.png",
      });
    }
  };

  // ── Add alert ─────────────────────────────────────────────────────────────
  const addAlert = () => {
    const sym = ticker.trim().toUpperCase();
    const tgt = parseFloat(price);
    if (!sym || isNaN(tgt) || tgt <= 0) return;
    const newAlert = {
      id: Date.now(),
      ticker: sym,
      targetPrice: tgt,
      direction,
      createdAt: new Date().toISOString().slice(0, 10),
      triggered: false,
    };
    setAlerts(prev => [newAlert, ...prev]);
    setTicker(""); setPrice("");
  };

  // ── Delete alert ──────────────────────────────────────────────────────────
  const deleteAlert = (id) => setAlerts(prev => prev.filter(a => a.id !== id));

  // ── Check prices every 30s ────────────────────────────────────────────────
  useEffect(() => {
    const activeAlerts = alerts.filter(a => !a.triggered);
    if (activeAlerts.length === 0) return;

    const checkNow = async () => {
      setChecking(true);
      const tickers = [...new Set(activeAlerts.map(a => a.ticker))];
      const prices = {};
      await Promise.allSettled(
        tickers.map(sym =>
          fetch(`https://finnhub.io/api/v1/quote?symbol=${sym}&token=${FINNHUB_KEY_ALERT}`)
            .then(r => r.json())
            .then(d => { if (d.c) prices[sym] = d.c; })
            .catch(() => {})
        )
      );
      setLastCheck(new Date().toLocaleTimeString());
      setLiveMap(prev => ({...prev, ...prices})); // update live prices for proximity bars

      setAlerts(prev => prev.map(a => {
        if (a.triggered) return a;
        const cur = prices[a.ticker];
        if (!cur) return a;
        const hit = (a.direction === "above" && cur >= a.targetPrice) ||
                    (a.direction === "below" && cur <= a.targetPrice);
        if (hit) {
          // Fire browser notification
          if (typeof Notification !== "undefined" && Notification.permission === "granted") {
            new Notification(`🔔 $${a.ticker} ${a.direction === "above" ? (isEN?"above":"superó") : (isEN?"below":"bajó de")} $${a.targetPrice}`, {
              body: `${isEN?"Current price":"Precio actual"}: $${cur.toFixed(2)}`,
              icon: "/logo_nexo.png",
              badge: "/favicon.svg",
              tag: `alert-${a.id}`,
            });
          }
          setFired(prev => ({ ...prev, [a.id]: cur }));
          return { ...a, triggered: true, triggeredAt: new Date().toLocaleTimeString(), triggeredPrice: cur };
        }
        return a;
      }));
      setChecking(false);
    };

    checkNow();
    const interval = setInterval(checkNow, 30000);
    return () => clearInterval(interval);
  }, [alerts.length, isEN]);

  // ── Colors & styles ───────────────────────────────────────────────────────
  const permColor = notifPerm === "granted" ? C.bull : notifPerm === "denied" ? C.bear : C.gold;
  const permLabel = notifPerm === "granted"
    ? (isEN ? "✓ Notifications active" : "✓ Notificaciones activas")
    : notifPerm === "denied"
    ? (isEN ? "✗ Blocked — enable in browser settings" : "✗ Bloqueado — activa en ajustes del navegador")
    : (isEN ? "Enable notifications" : "Activar notificaciones");

  const activeCount  = alerts.filter(a => !a.triggered).length;
  const firedCount   = alerts.filter(a => a.triggered).length;

  // ── Smart portfolio suggestions ───────────────────────────────────────────
  const alertedTickers = new Set(alerts.map(a => a.ticker));
  const suggestedTickers = portfolioTickers.filter(t => !alertedTickers.has(t)).slice(0, 3);

  return (
    <div style={{ maxWidth: 680, margin: "0 auto", padding: "20px 16px", fontFamily: "system-ui,-apple-system,sans-serif" }}>

      {/* Header */}
      <div style={{ marginBottom: 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6 }}>
          <div style={{ width: 44, height: 44, borderRadius: 14, background: "rgba(0,102,255,0.12)", border: "1.5px solid rgba(0,102,255,0.25)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22 }}>🔔</div>
          <div>
            <div style={{ fontWeight: 900, fontSize: 22, color: C.text, letterSpacing: -0.5 }}>
              {isEN ? "Alert Center" : "Centro de Alertas"}
            </div>
            <div style={{ fontSize: 13, color: C.muted }}>
              {isEN ? "Get notified when prices hit your targets" : "Recibe alertas cuando los precios lleguen a tus objetivos"}
            </div>
          </div>
        </div>

        {/* Stats row */}
        <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
          {[
            { label: isEN ? "Active" : "Activas", value: activeCount, color: C.accent },
            { label: isEN ? "Triggered" : "Disparadas", value: firedCount, color: C.bull },
            { label: isEN ? "Total" : "Total", value: alerts.length, color: C.muted },
          ].map(s => (
            <div key={s.label} style={{ flex: 1, background: C.card, border: `1px solid ${C.border}`, borderRadius: 12, padding: "10px 14px", textAlign: "center" }}>
              <div style={{ fontWeight: 900, fontSize: 20, color: s.color }}>{s.value}</div>
              <div style={{ fontSize: 11, color: C.muted, fontWeight: 600 }}>{s.label}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Notification permission banner */}
      <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: "14px 16px", marginBottom: 20, display: "flex", alignItems: "center", gap: 12 }}>
        <span style={{ fontSize: 22 }}>🔕</span>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 700, fontSize: 13, color: C.text, marginBottom: 2 }}>
            {isEN ? "Browser Notifications" : "Notificaciones del navegador"}
          </div>
          <div style={{ fontSize: 12, color: permColor, fontWeight: 600 }}>{permLabel}</div>
        </div>
        {notifPerm !== "granted" && notifPerm !== "denied" && (
          <button onClick={requestPermission}
            style={{ background: C.accent, color: "#fff", border: "none", borderRadius: 10, padding: "8px 18px", fontSize: 13, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}>
            {isEN ? "Enable" : "Activar"}
          </button>
        )}
      </div>

      {/* ── Smart Portfolio Suggestions ───────────────────────────────────────── */}
      {suggestedTickers.length > 0 && (
        <div style={{ background: C.card, border: `1px solid rgba(0,102,255,0.25)`, borderRadius: 16, padding: "16px 18px", marginBottom: 20 }}>
          <div style={{ fontWeight: 800, fontSize: 14, color: C.text, marginBottom: 12, display: "flex", alignItems: "center", gap: 8 }}>
            <span>💡</span>
            {isEN ? "Suggestions from your Portfolio" : "Sugerencias de tu Portafolio"}
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {suggestedTickers.map(sym => (
              <div key={sym} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ fontWeight: 800, fontSize: 13, color: C.text, minWidth: 60 }}>${sym}</span>
                <span style={{ fontSize: 12, color: C.muted, flex: 1 }}>
                  {isEN ? "You hold this — create a stop-loss alert?" : "Tienes esta posición — ¿crear alerta stop-loss?"}
                </span>
                <button onClick={() => { setTicker(sym); setDirection("below"); }}
                  style={{ background: "rgba(0,102,255,0.10)", border: "1px solid rgba(0,102,255,0.25)", borderRadius: 8, padding: "5px 12px", fontSize: 12, fontWeight: 700, color: C.accent, cursor: "pointer", whiteSpace: "nowrap" }}>
                  {isEN ? "Set Alert" : "Crear alerta"}
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Add alert form */}
      <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 16, padding: "18px 18px 20px", marginBottom: 20 }}>
        <div style={{ fontWeight: 800, fontSize: 15, color: C.text, marginBottom: 14 }}>
          {isEN ? "➕ New Price Alert" : "➕ Nueva Alerta de Precio"}
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end" }}>
          {/* Ticker */}
          <div style={{ flex: "1 1 90px", minWidth: 80 }}>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, marginBottom: 4 }}>Ticker</div>
            <input
              value={ticker}
              onChange={e => setTicker(e.target.value.toUpperCase())}
              onKeyDown={e => e.key === "Enter" && addAlert()}
              placeholder="AAPL"
              maxLength={8}
              style={{ width: "100%", background: "var(--c-bg)", border: `1px solid ${C.border}`, borderRadius: 10, padding: "9px 12px", fontSize: 13, fontWeight: 700, color: C.text, outline: "none", boxSizing: "border-box" }}
            />
          </div>
          {/* Direction */}
          <div style={{ flex: "1 1 110px", minWidth: 100 }}>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, marginBottom: 4 }}>
              {isEN ? "When price is" : "Cuando precio"}
            </div>
            <select value={direction} onChange={e => setDirection(e.target.value)}
              style={{ width: "100%", background: "var(--c-bg)", border: `1px solid ${C.border}`, borderRadius: 10, padding: "9px 12px", fontSize: 13, color: C.text, outline: "none", boxSizing: "border-box", cursor: "pointer" }}>
              <option value="above">{isEN ? "≥ Above" : "≥ Sobre"}</option>
              <option value="below">{isEN ? "≤ Below" : "≤ Bajo"}</option>
            </select>
          </div>
          {/* Price */}
          <div style={{ flex: "1 1 90px", minWidth: 80 }}>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, marginBottom: 4 }}>
              {isEN ? "Target $" : "Precio $"}
            </div>
            <input
              value={price}
              onChange={e => setPrice(e.target.value)}
              onKeyDown={e => e.key === "Enter" && addAlert()}
              placeholder="150.00"
              type="number"
              min="0"
              style={{ width: "100%", background: "var(--c-bg)", border: `1px solid ${C.border}`, borderRadius: 10, padding: "9px 12px", fontSize: 13, color: C.text, outline: "none", boxSizing: "border-box" }}
            />
          </div>
          {/* Add button */}
          <button onClick={addAlert}
            style={{ flex: "0 0 auto", background: C.accent, color: "#fff", border: "none", borderRadius: 10, padding: "10px 22px", fontSize: 13, fontWeight: 800, cursor: "pointer", whiteSpace: "nowrap", alignSelf: "flex-end" }}>
            {isEN ? "Add Alert" : "Agregar"}
          </button>
        </div>

        {/* Check status */}
        <div style={{ marginTop: 12, display: "flex", alignItems: "center", gap: 8 }}>
          <div style={{ width: 7, height: 7, borderRadius: "50%", background: checking ? C.gold : activeCount > 0 ? C.bull : C.muted, animation: checking ? "pulse 1s infinite" : "none" }}/>
          <span style={{ fontSize: 11, color: C.muted }}>
            {checking
              ? (isEN ? "Checking prices..." : "Verificando precios...")
              : lastCheck
              ? (isEN ? `Last check: ${lastCheck}` : `Última verificación: ${lastCheck}`)
              : (isEN ? "Checks every 30 seconds" : "Verifica cada 30 segundos")}
          </span>
        </div>
      </div>

      {/* Alerts list */}
      {alerts.length === 0 ? (
        <div style={{ textAlign: "center", padding: "40px 20px", background: C.card, border: `1px dashed ${C.border}`, borderRadius: 16 }}>
          <div style={{ fontSize: 36, marginBottom: 10 }}>🔔</div>
          <div style={{ fontWeight: 700, color: C.text, marginBottom: 4 }}>
            {isEN ? "No alerts yet" : "Sin alertas aún"}
          </div>
          <div style={{ fontSize: 13, color: C.muted }}>
            {isEN ? "Add a price alert above to get started." : "Agrega una alerta de precio arriba para empezar."}
          </div>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {/* Active alerts first */}
          {alerts.filter(a => !a.triggered).length > 0 && (
            <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, letterSpacing: 0.5, textTransform: "uppercase", marginBottom: 4 }}>
              {isEN ? "Active Alerts" : "Alertas Activas"}
            </div>
          )}
          {alerts.filter(a => !a.triggered).map(a => {
            const cur = liveMap[a.ticker];
            const pct = cur
              ? (a.direction==="above"
                  ? Math.min(cur / a.targetPrice * 100, 100)
                  : Math.min(a.targetPrice / cur * 100, 100))
              : null;
            const dist = cur ? Math.abs(cur - a.targetPrice) : null;
            const isNear = pct !== null && pct >= 98;
            return (
              <div key={a.id} style={{ background: C.card, border: `1.5px solid ${isNear?"rgba(245,158,11,0.5)":a.direction==="above"?"rgba(22,163,74,0.25)":"rgba(220,38,38,0.25)"}`, borderRadius: 14, padding: "14px 16px 12px", transition: "border-color 0.3s" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                  <div style={{ width: 36, height: 36, borderRadius: 10, background: a.direction==="above"?C.bullBg:C.bearBg, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16, flexShrink: 0 }}>
                    {a.direction === "above" ? "📈" : "📉"}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                      <span style={{ fontWeight: 800, fontSize: 14, color: C.text }}>${a.ticker}</span>
                      <span style={{ background: a.direction==="above"?C.bullBg:C.bearBg, color: a.direction==="above"?C.bull:C.bear, borderRadius: 20, padding: "1px 8px", fontSize: 11, fontWeight: 700 }}>
                        {a.direction === "above" ? "≥" : "≤"} ${a.targetPrice}
                      </span>
                      {isNear && (
                        <span style={{ background: "rgba(245,158,11,0.15)", color: C.gold, borderRadius: 20, padding: "1px 8px", fontSize: 11, fontWeight: 800, animation: "pulse 1.2s infinite" }}>
                          🔥 {isEN?"NEAR":"CERCA"}
                        </span>
                      )}
                      {cur && !isNear && (
                        <span style={{ fontSize: 11, color: C.muted }}>
                          {isEN?"Now":"Ahora"}: ${cur.toFixed(2)}
                        </span>
                      )}
                    </div>
                    <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>
                      {isEN ? "Added" : "Creada"} {a.createdAt}
                      {dist !== null && ` · ${isEN?"$"+dist.toFixed(2)+" away":"a $"+dist.toFixed(2)+" del objetivo"}`}
                    </div>
                  </div>
                  <button onClick={() => deleteAlert(a.id)}
                    style={{ background: "none", border: "none", color: C.muted, fontSize: 18, cursor: "pointer", padding: "4px 6px", borderRadius: 8, opacity: 0.6 }}>×</button>
                </div>
                {/* ── Proximity bar ── */}
                {pct !== null && (
                  <div style={{ marginTop: 10 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                      <span style={{ fontSize: 10, color: C.muted, fontWeight: 600 }}>
                        {isEN ? "Proximity to target" : "Proximidad al objetivo"}
                      </span>
                      <span style={{ fontSize: 10, fontWeight: 700, color: isNear ? C.gold : a.direction==="above" ? C.bull : C.bear }}>
                        {pct.toFixed(1)}%
                      </span>
                    </div>
                    <div style={{ height: 5, borderRadius: 99, background: C.border, overflow: "hidden" }}>
                      <div style={{
                        height: "100%",
                        width: `${pct}%`,
                        borderRadius: 99,
                        background: isNear
                          ? `linear-gradient(90deg, ${a.direction==="above"?C.bull:C.bear}, ${C.gold})`
                          : a.direction==="above" ? C.bull : C.bear,
                        transition: "width 0.6s ease",
                      }}/>
                    </div>
                  </div>
                )}
              </div>
            );
          })}

          {/* ── Recent Activations feed ── */}
          {alerts.filter(a => a.triggered).length > 0 && (
            <>
              <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, letterSpacing: 0.5, textTransform: "uppercase", margin: "14px 0 8px", display: "flex", alignItems: "center", gap: 6 }}>
                <span>📡</span>{isEN ? "Recent Activations" : "Activaciones Recientes"}
              </div>
              <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 16, overflow: "hidden" }}>
                {alerts.filter(a => a.triggered).map((a, idx, arr) => (
                  <div key={a.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderBottom: idx < arr.length-1 ? `1px solid ${C.border}` : "none" }}>
                    <div style={{ width: 10, height: 10, borderRadius: "50%", background: C.bull, flexShrink: 0 }}/>
                    <div style={{ flex: 1 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                        <span style={{ fontWeight: 800, fontSize: 13, color: C.text }}>${a.ticker}</span>
                        <span style={{ background: C.bullBg, color: C.bull, borderRadius: 20, padding: "1px 8px", fontSize: 11, fontWeight: 700 }}>✅ {isEN?"Triggered":"Disparada"}</span>
                        {a.triggeredAt && <span style={{ fontSize: 11, color: C.muted }}>{a.triggeredAt}</span>}
                      </div>
                      <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>
                        {a.direction === "above" ? "≥" : "≤"} ${a.targetPrice}
                        {a.triggeredPrice ? ` → $${Number(a.triggeredPrice).toFixed(2)}` : ""}
                      </div>
                    </div>
                    <button onClick={() => deleteAlert(a.id)}
                      style={{ background: "none", border: "none", color: C.muted, fontSize: 18, cursor: "pointer", padding: "4px 6px", borderRadius: 8, opacity: 0.6 }}>×</button>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      )}

      {/* Info footer */}
      <div style={{ marginTop: 20, padding: "14px 16px", background: C.card, border: `1px solid ${C.border}`, borderRadius: 12, display: "flex", gap: 10, alignItems: "flex-start" }}>
        <span style={{ fontSize: 18 }}>ℹ️</span>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.6 }}>
          {isEN
            ? "Prices are checked every 30 seconds via Finnhub. Keep this page open to receive real-time alerts. Browser notifications require permission."
            : "Los precios se verifican cada 30 segundos via Finnhub. Mantén esta página abierta para recibir alertas en tiempo real. Las notificaciones del navegador requieren permiso."}
        </div>
      </div>
    </div>
  );
}

